const BAK=n=>KEY+'_bak'+n, NBAK=5;
function load(){
  try{ DB=JSON.parse(localStorage.getItem(KEY)); }catch(e){ DB=null; }
  if(!DB||!DB.users){                       // перенос данных с прошлой версии приложения
    try{ const old=JSON.parse(localStorage.getItem('selcrm_v1'));
      if(old&&old.users){ DB=old; DB.migratedFrom='selcrm_v1'; } }catch(e){}
  }
  if(!DB||!DB.users){                       // основная запись потеряна — поднимаем свежую копию
    for(let i=0;i<NBAK&&!(DB&&DB.users);i++){
      try{ const b=JSON.parse(localStorage.getItem(BAK(i))); if(b&&b.data&&b.data.users){DB=b.data;
        setTimeout(()=>toast('Данные восстановлены из копии от '+new Date(b.at).toLocaleString('ru-RU')),800);} }catch(e){}
    }
  }
  if(!DB||!DB.users) DB=blankDB();
  DB.drafts=DB.drafts||{}; DB.formDrafts=DB.formDrafts||{}; DB.seq=DB.seq||{}; DB.sync=DB.sync||{url:'',at:0};
  DB.settings=DB.settings||{waOperator:''}; DB.bakAt=DB.bakAt||0; DB.deleted=DB.deleted||{};
  DB.presence=DB.presence||{}; DB.queue=DB.queue||[]; DB.since=DB.since||0;
  DB.auth=DB.auth||{token:'',exp:0,uid:''}; DB.local=DB.local||{};
  DB.schemaVersion=DB.schemaVersion||SCHEMA; DB.skew=DB.skew||0;
  DB.presAt=DB.presAt||0; DB.parked=DB.parked||{}; DB.dense=0;
  DB.settings.targets=DB.settings.targets||{};
  DB.settings.suppliers=Array.isArray(DB.settings.suppliers)?DB.settings.suppliers:[];
  DB.photos=DB.photos||{};
  DB.photosAt=Number(DB.photosAt)||0;
  DB.clientBook=Array.isArray(DB.clientBook)?DB.clientBook:[];
  DB.local.favorites=Array.isArray(DB.local.favorites)?DB.local.favorites:[];
  DB.sync=DB.sync||{url:'',at:0,err:'',code:''};
  const cut=Date.now()-90*864e5;                       // метки старше 90 дней не нужны
  for(const k in DB.deleted) if(DB.deleted[k]<cut) delete DB.deleted[k];
  DB.orders=DB.orders.filter(o=>!(DB.deleted[o.id]>=(o.updatedAt||0)));
  MANAGERS.forEach(m=>{ if(!DB.users[m.id]) DB.users[m.id]={id:m.id,name:m.name,role:m.role,pass:null}; });
}
function autoBackup(){                      // копия раз в час, кольцо из 5 слотов
  if(Date.now()-(DB.bakAt||0) < 36e5) return;
  DB.bakAt=Date.now();
  try{
    for(let i=NBAK-1;i>0;i--){ const p=localStorage.getItem(BAK(i-1)); if(p) localStorage.setItem(BAK(i),p); }
    localStorage.setItem(BAK(0),JSON.stringify({at:Date.now(),data:DB}));
  }catch(e){ try{ localStorage.removeItem(BAK(NBAK-1)); }catch(_){} }
}
function save(){
  try{ localStorage.setItem(KEY,JSON.stringify(DB)); autoBackup(); }
  catch(e){
    try{ for(let i=NBAK-1;i>=2;i--) localStorage.removeItem(BAK(i));
         localStorage.setItem(KEY,JSON.stringify(DB)); toast('Память была переполнена, старые копии удалены'); }
    catch(_){
      /* последняя попытка: сворачиваем старые заявки и пишем ещё раз */
      const r=compactOld(90);
      try{ localStorage.setItem(KEY,JSON.stringify(DB));
        toast(r.n?('Память была переполнена — свёрнуто старых заявок: '+r.n)
                 :'Не удалось сохранить: память браузера переполнена'); }
      catch(__){ toast('Не удалось сохранить: память браузера переполнена'); }
    }
  }
  flush();
}
/* Сворачивание старых заявок: состав позиций убирается, суммы и оплаты остаются.
   Нужно, чтобы память браузера не переполнилась через год работы. */
function compactOld(days){
  days=days||120; const edge=addDays(today(),-days);
  let n=0, freed=0;
  DB.orders.forEach(o=>{
    if(o.arch||!o.shipDate||o.shipDate>=edge) return;
    if(!(o.items&&o.items.length)) return;
    freed+=JSON.stringify(o.items).length;
    o.archItems=o.items.length;
    o.archUnits=o.items.reduce((s,i)=>s+(+i.q||0),0);
    o.items=[]; o.arch=1; n++;
  });
  if(n) save();
  return {n,freed};
}
function backupList(){
  const out=[];
  for(let i=0;i<NBAK;i++){ try{ const b=JSON.parse(localStorage.getItem(BAK(i)));
    if(b&&b.at) out.push({i,at:b.at,orders:(b.data.orders||[]).length}); }catch(e){} }
  return out;
}
function dbSize(){ let n=0; try{ for(let i=0;i<NBAK;i++){const v=localStorage.getItem(BAK(i)); if(v)n+=v.length;}
  n+=(localStorage.getItem(KEY)||'').length; }catch(e){} return n; }

