const ART_RE=/^[0-9][0-9A-Za-z/._-]*$/;
function splitRows(text){
  const line=text.split(/\r?\n/).find(l=>l.trim())||'';
  const c=(line.match(/;/g)||[]).length,t=(line.match(/\t/g)||[]).length,k=(line.match(/,/g)||[]).length;
  const D=t>=c&&t>=k?'\t':(c>=k?';':',');
  const rows=[];let row=[],cell='',q=false;
  for(let i=0;i<text.length;i++){const ch=text[i];
    if(q){ if(ch==='"'){ if(text[i+1]==='"'){cell+='"';i++;} else q=false; } else cell+=ch; continue; }
    if(ch==='"'){q=true;continue}
    if(ch===D){row.push(cell);cell='';continue}
    if(ch==='\n'){row.push(cell);rows.push(row);row=[];cell='';continue}
    if(ch==='\r')continue; cell+=ch;}
  if(cell!==''||row.length){row.push(cell);rows.push(row)}
  return rows.filter(r=>r.some(c=>String(c).trim()!==''));
}
/* Числа из выгрузок 1С приходят по-разному:
   «102.000» это 102 (три знака после точки — дробная часть),
   «2,612» и «15,000» это 2612 и 15000 (запятая делит тысячи),
   «2,5» это два с половиной. Решаем по виду самой ячейки. */
function num(v){
  let s=String(v).replace(/[\s\u00A0\u202F]/g,'');
  if(!s||s==='-') return null;
  const neg=/^-/.test(s); if(neg) s=s.slice(1);
  if(/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) s=s.replace(/,/g,'');   // 15,000 → 15000
  else s=s.replace(',','.');                                        // 2,5 → 2.5
  if(!/^\d+(\.\d+)?$/.test(s)) return null;
  return (neg?-1:1)*parseFloat(s);
}
function detectNumFormat(){}
function parseStock(text){
  detectNumFormat(text);
  const rows=splitRows(text); let date='';
  for(const r of rows){const j=r.findIndex(c=>/^\s*С\s+\d{1,2}\.\d{1,2}\.\d{2,4}/i.test(String(c)));
    if(j>-1){date=String(r[j]).trim();break}}
  const nameColFor=h=>{ if(h<0)return 0;
    const j=rows[h].findIndex(c=>/номенклатур|наименован|артикул|товар|позиц/i.test(String(c)));return j>-1?j:0};
  const extract=(h,qc,nc)=>{const map={};let n=0;
    for(let i=(h>-1?h+1:0);i<rows.length;i++){const r=rows[i];if(!r||!r.length)continue;
      const raw=String(r[nc]||'').trim();if(!raw)continue;
      let art=(raw.split(/\s+/)[0]||'').trim();
      if(!ART_RE.test(art)){
        /* строка без артикула: берём её как бонусную позицию по названию */
        const bk=bkey(raw); if(!BONUS_MAP[bk]) continue; art=bk;
      }
      let q; if(h>-1&&qc>-1){ q=num(r[qc]); if(q===null)q=0; }
      else{ q=null; for(let c=r.length-1;c>nc;c--){const v=num(r[c]);if(v!==null){q=v;break}} if(q===null)continue; }
      if(!(art in map)){map[art]=q;n++}}
    return {map,count:n}};
  const cands=[];
  for(let i=0;i<Math.min(rows.length,30);i++) rows[i].forEach((c,j)=>{
    const s=String(c).toLowerCase().trim();
    if(s.length<=30&&/остат|кол-?во|количеств/.test(s)&&!/резерв|начальн/.test(s)) cands.push([i,j,/конечн/.test(s)?1.05:1]);});
  cands.push([-1,-1,1]);
  let best={map:{},count:0},bs=-1;
  for(const [h,q,w] of cands){const r=extract(h,q,nameColFor(h));if(r.count*w>bs){bs=r.count*w;best=r}}
  return {map:best.map,count:best.count,date};
}

/* фактический остаток = файл минус заказы, оформленные ПОСЛЕ загрузки файла */
let USED={};
function recalcUsed(){
  USED={};
  /* Занятый остаток считает сервер по ВСЕМ заявкам — иначе менеджер
     не видит, что уже забрали коллеги, и остаток у него завышен. */
  const srv=DB.usedSrv;
  if(srv&&typeof srv==='object'){
    for(const a in srv) USED[a]=srv[a];
    /* заявки, ещё не ушедшие на сервер, он учесть не мог */
    const wait=new Set(DB.queue.filter(op=>op.type==='order.save'&&op.order).map(op=>op.order.id));
    for(const o of DB.orders){
      if(!wait.has(o.id)||o.status==='Отменён') continue;
      if(o.createdAt<=(DB.stock.at||0)) continue;
      const back=MONEY.retQty(o);
      for(const i of o.items) USED[i.a]=(USED[i.a]||0)+Math.max(0,i.q-(back[i.a]||0));
    }
    return;
  }
  /* база ещё не подключалась — считаем по своим заявкам */
  for(const o of DB.orders){
    if(o.status==='Отменён') continue;
    if(o.createdAt<=(DB.stock.at||0)) continue;
    const back=MONEY.retQty(o);
    for(const i of o.items) USED[i.a]=(USED[i.a]||0)+Math.max(0,i.q-(back[i.a]||0));
  }
}
function stockOf(a){ return Math.max(0,(DB.stock.map[a]??0)-(USED[a]||0)); }

