const PROD={}; CATALOG.prods.forEach(p=>PROD[p.a]=p);
function basePrice(p){return p.p}
/* Скидка на весь прайс задаётся администратором и расходится по всем устройствам */
function discOf(){ const d=DB.settings&&DB.settings.discount; return (d===undefined||d===null)?CFG.СКИДКА_ПО_УМОЛЧАНИЮ:d; }
function promoPrice(p){return Math.round(p.p*(1-discOf()))}
/* Цена по прайсу без ручной правки — чтобы можно было к ней вернуться */
function viewPriceBase(p){
  const cfg=meCfg();
  return cfg.seeDisc?Math.round(p.p*(1-discOf())):p.p;
}
/* Что именно видит текущий пользователь по конкретной позиции */
function viewPrice(p){
  const cfg=meCfg(), d=draft(), own=d.prices[p.a];
  if(!cfg.seeDisc){                     // цены без скидки, свои, скидку не показываем
    return {base:p.p, disc:0, now:(own!=null?own:p.p), edit:!!cfg.freePrice, showDisc:false};
  }
  const disc=discOf(), auto=Math.round(p.p*(1-disc));
  return {base:p.p, disc, now:(cfg.freePrice&&own!=null?own:auto), edit:!!cfg.freePrice, showDisc:true};
}
function draft(){ if(!ME) return {items:{},prices:{},bonus:{}};
  DB.drafts[ME.id]=DB.drafts[ME.id]||{items:{},prices:{},bonus:{}};
  DB.drafts[ME.id].bonus=DB.drafts[ME.id].bonus||{};
  return DB.drafts[ME.id]; }
function cartLines(){
  const d=draft(),out=[];
  for(const a in d.items){const q=d.items[a],p=PROD[a];if(!q||!p)continue;
    const v=viewPrice(p);
    out.push({a,n:p.n,q,base:v.base,disc:v.disc,price:v.now,sum:MONEY.lineSum(v.now,q)});}
  return out;
}
/* Бонусные строки: цена и сумма всегда ноль, в итог не попадают */
function bonusLines(){
  const d=draft(),out=[];
  for(const k in d.bonus){const q=d.bonus[k]; if(!q||!BONUS_MAP[k])continue;
    out.push({a:k,n:bonusName(k),q,base:0,disc:0,price:0,sum:0,bonus:true});}
  return out;
}
function setBonus(k,q){
  if(!BONUS_MAP[k]) return;
  const d=draft(), max=stockOf(k);
  q=Math.max(0,Math.min(max,parseInt(q,10)||0));
  if(q) d.bonus[k]=q; else delete d.bonus[k];
  save(); recalcUsed();
}
function setQty(a,v){
  const d=draft(),max=stockOf(a);
  v=Math.max(0,Math.min(isFinite(v)?v:0,max));
  if(v<=0){delete d.items[a];delete d.prices[a]} else d.items[a]=v;
  save(); paintFab(); if(PFILTER&&$('#plist')) paintList();
}
function toneColor(name){
  const m=String(name).match(/(?:^|[\s-])(\d{1,2})\.(\d{1,3})(?!\d)/); if(!m)return null;
  const lvl=Math.min(10,Math.max(1,+m[1])),t=+m[2][0];
  const T={0:[32,10],1:[205,7],2:[288,20],3:[43,48],4:[22,62],5:[352,42],6:[4,68],7:[26,26],8:[262,28],9:[212,20]};
  const [h,s]=T[t]||[30,12];
  return `hsl(${h} ${Math.min(80,Math.round(s*(.55+lvl/10*.75)))}% ${9+(lvl-1)*8.6}%)`;
}

