async function nextNo(){
  const st=today().slice(2).replace(/-/g,''), appId=String(ME&&ME.id||'user');
  const k=st+'_'+appId; let n=Number(DB.seq[k]||0)+1;
  /* Firebase sequence is atomic across phones/computers. This prevents duplicate
     human-readable order numbers when one manager works on two devices. */
  if(typeof FBDB!=='undefined'&&FBDB&&typeof FBAUTH!=='undefined'&&FBAUTH&&FBAUTH.currentUser){
    const ref=FBDB.collection('sequences').doc(fbSafeId(k));
    n=await FBDB.runTransaction(async tx=>{
      const s=await tx.get(ref), cur=s.exists?Number((s.data()||{}).n||0):0;
      const next=Math.max(cur,Number(DB.seq[k]||0))+1;
      tx.set(ref,{key:k,appId,date:st,n:next,updatedAt:Date.now()},{merge:true});
      return next;
    });
  }
  DB.seq[k]=n; persist();
  const pfx=appId.slice(0,2).toUpperCase();
  return `ЗК-${st}-${pfx}${String(n).padStart(3,'0')}`;
}
function myOrders(){ if(!ME) return []; return DB.orders.filter(o=>isAdmin()||o.uid===ME.id); }
/* ЕДИНЫЙ РАСЧЁТ. Любая сумма в приложении считается только здесь:
   заявка, бланк, PDF, дебиторка, отчёты — одни и те же формулы. */
const MONEY={
  lineSum:(price,q)=>Math.round((+price||0)*(+q||0)),
  baseSum:(base,q)=>Math.round((+base||0)*(+q||0)),
  totals(items){
    const list=items||[];
    const total=list.reduce((s,i)=>s+MONEY.lineSum(i.price,i.q),0);
    const totalBase=list.reduce((s,i)=>s+MONEY.baseSum(i.base,i.q),0);
    return {total,totalBase,saving:Math.max(0,totalBase-total),units:list.reduce((s,i)=>s+(+i.q||0),0)};
  },
  paid(o){ return (o.payments||[]).filter(p=>!p.wait&&p.state!=='отклонён').reduce((s,p)=>s+Math.max(0,+p.s||0),0); },
  /* оплаты, ещё не подтверждённые администратором */
  unconfirmed(o){ return (o.payments||[]).filter(p=>p.wait).reduce((s,p)=>s+Math.max(0,+p.s||0),0); },
  /* дни просрочки считаем от даты наступления обязательства */
  overdueDays(o,todayIso){
    const ship=MONEY.shipDay(o);
    if(MONEY.debt(o)<=0||!ship) return 0;
    const due=o.payDays?MONEY.dueOf(o):ship;
    if(!due||due>=todayIso) return 0;
    return Math.max(0,Math.round((new Date(todayIso+'T12:00:00')-new Date(due+'T12:00:00'))/86400000));
  },
  /* график платежей: ближайшая непокрытая часть */
  nextPart(o){
    if(!o.plan||!o.plan.length) return null;
    let paid=MONEY.paid(o);
    for(const p of o.plan){ if(paid>=p.s){ paid-=p.s; continue; } return {d:p.d,left:p.s-paid}; }
    return null;
  },
  planOverdue(o,todayIso){
    if(!o.plan||!o.plan.length) return false;
    const n=MONEY.nextPart(o);
    return !!(n&&n.d<todayIso);
  },
  /* Дата, по которой судим о просрочке: при графике — ближайшая непокрытая
     часть, иначе обычная дата возврата денег. Одна функция на всё приложение. */
  /* День, когда товар реально уехал: факт, если отмечен, иначе план */
  shipDay(o){ return o.fact||o.shipDate||''; },
  dueOf(o){
    if(o.plan&&o.plan.length){ const n=MONEY.nextPart(o); if(n) return n.d; }
    /* срок денег считаем от фактической отгрузки, а не от плановой */
    if(o.fact&&o.payDays) return addDays(o.fact,+o.payDays);
    return o.dueDate||o.shipDate||'';
  },
  /* Сколько частей графика уже закрыто */
  planDone(o){
    if(!o.plan||!o.plan.length) return null;
    let paid=MONEY.paid(o), done=0;
    for(const p of o.plan){ if(paid>=p.s){ paid-=p.s; done++; } else break; }
    return {done,total:o.plan.length};
  },
  writtenOff(o){ return o.status==='Списан'; },
  /* в расчёт идут только ПРИНЯТЫЕ возвраты — до проверки долг и остаток не трогаем */
  returned(o){ return (o.returns||[]).filter(r=>r.state==='принят')
                 .reduce((s,r)=>s+Math.max(0,+r.sum||0),0); },
  pendingRet(o){ return (o.returns||[]).filter(r=>!r.state||r.state==='ждёт проверки').length; },
  /* к оплате = отгружено минус возвращённое */
  net(o){ return Math.max(0,(+o.total||0)-MONEY.returned(o)); },
  debt(o){ if(o.status==='Отменён'||o.status==='Списан') return 0;
    return Math.max(0,MONEY.net(o)-MONEY.paid(o)); },
  over(o){ return Math.max(0,MONEY.paid(o)-MONEY.net(o)); },
  /* сколько штук каждого артикула вернули по заявке */
  retQty(o){ const m={}; (o.returns||[]).filter(r=>r.state==='принят')
    .forEach(r=>(r.items||[]).forEach(i=>{ m[i.a]=(m[i.a]||0)+(+i.q||0); })); return m; },
  /* сколько уже заявлено к возврату, включая непроверенное — чтобы не вернуть дважды */
  retClaimed(o){ const m={}; (o.returns||[]).filter(r=>r.state!=='отклонён')
    .forEach(r=>(r.items||[]).forEach(i=>{ m[i.a]=(m[i.a]||0)+(+i.q||0); })); return m; },
  discPrice:(base,disc)=>Math.round((+base||0)*(1-(+disc||0)))
};
function paidOf(o){ return MONEY.paid(o); }
function debtOf(o){ return MONEY.debt(o); }
function editable(o){ const born=o.serverCreatedAt||o.createdAt||0; return isAdmin() || (o.uid===ME.id && (Date.now()+(DB.skew||0))-born < 864e5); }

