/* ---------- РАЗБОР ПО ТОВАРУ: ходовое, среднее, залежи ---------- */
function abcRows(days=90){
  const from=addDays(today(),-days);
  const sold={}, last={};
  myOrders().filter(o=>o.status!=='Отменён'&&(o.shipDate||'')>=from)
    .forEach(o=>{
      const back=MONEY.retQty(o);
      (o.items||[]).forEach(i=>{
        const q=Math.max(0,i.q-(back[i.a]||0));
        if(!q) return;
        sold[i.a]=sold[i.a]||{a:i.a,n:i.n,q:0,sum:0};
        sold[i.a].q+=q; sold[i.a].sum+=MONEY.lineSum(i.price,q);
        if(!last[i.a]||o.shipDate>last[i.a]) last[i.a]=o.shipDate;
      });
    });
  recalcUsed();
  const rows=CATALOG.prods.map(p=>{
    const s=sold[p.a];
    return {a:p.a,n:p.n,q:s?s.q:0,sum:s?s.sum:0,last:last[p.a]||'',stock:stockOf(p.a)};
  }).filter(r=>r.stock>0||r.q>0);
  rows.sort((x,y)=>y.sum-x.sum);
  const total=rows.reduce((s,r)=>s+r.sum,0);
  let acc=0;
  rows.forEach(r=>{ acc+=r.sum; r.share=total?r.sum/total:0;
    r.grp=!r.q?'Не продавалось':(acc<=total*0.8?'Ходовые':(acc<=total*0.95?'Средние':'Слабые')); });
  return {rows,total,days};
}
function vAbc(){
  const {rows,total,days}=abcRows();
  const dead=rows.filter(r=>r.grp==='Не продавалось'&&r.stock>0);
  const deadSum=dead.length;
  const grp=(name,list,note)=>list.length?`<div class="sec">${name} · ${list.length}</div>
    <div class="card pad">${note?`<div class="note g">${note}</div>`:''}${list.slice(0,60).map(r=>
      `<div class="sums" style="padding:7px 0;border-bottom:1px solid var(--soft)">
        <span style="min-width:0;flex:1;color:var(--ink)">
          <span class="mono" style="font-size:11px;color:var(--acc)">${esc(r.a)}</span><br>
          <span style="font-size:13.5px">${esc(r.n)}</span><br>
          <span style="font-size:11.5px;color:var(--mut)">на складе ${r.stock}${r.last?' · последняя отгрузка '+ruDate(r.last):''}</span>
        </span>
        <b style="white-space:nowrap">${r.q?r.q+' шт<br><span style="font-size:11.5px;color:var(--mut)">'+money(r.sum)+'</span>':'—'}</b>
      </div>`).join('')}</div>`:'';
  sheet('Что берут и что лежит',`
    <div class="note g">За последние ${days} дней отгружено на <b>${money(total)} ${CFG.ВАЛЮТА}</b>.
      Разбито по вкладу в выручку: ходовые, средние, слабые и залежи.</div>
    ${deadSum?`<div class="note">На складе лежит <b>${deadSum}</b> ${plural(deadSum,'позиция','позиции','позиций')},
      которые не продавались ни разу за ${days} дней.</div>`:''}
    ${grp('Ходовые · дают 80% выручки',rows.filter(r=>r.grp==='Ходовые'),'Эти позиции нельзя терять со склада.')}
    ${grp('Средние · следующие 15% выручки',rows.filter(r=>r.grp==='Средние'))}
    ${grp('Слабые · остальные 5%',rows.filter(r=>r.grp==='Слабые'))}
    ${grp('Залежи · не продавались',dead,'Кандидаты на акцию или возврат поставщику.')}
    <div class="btns"><button class="btn" id="abcXls">Выгрузить в Excel</button></div>`,
  el=>{
    el.querySelector('#abcXls').addEventListener('click',async()=>{
      try{
        toast('Готовлю Excel…');
        const head=[['Группа','Артикул','Наименование','Продано, шт','Сумма','Доля %','На складе','Последняя отгрузка']];
        rows.forEach(r=>head.push([r.grp,r.a,r.n,r.q,r.sum,Math.round(r.share*1000)/10,r.stock,r.last?ruDate(r.last):'']));
        await saveXLSX('Trade Agent Manager — разбор по товару '+today()+'.xlsx',[{name:'Товары',rows:head}]);
        toast('Файл сохранён в «Загрузки»');
      }catch(e){ toast('Не удалось: '+String(e.message||e).slice(0,60)); }
    });
  });
}

