async function vAudit(){
  sheet('Журнал действий','<div class="empty"><b>Загружаю журнал…</b><span>Собираю последние события сервера</span></div>');
  try{
    const r=await api('/audit?limit=200',{timeout:15000});
    const log=(r.log||[]).slice().sort((a,b)=>(b.at||0)-(a.at||0));
    const todayKey=new Date().toLocaleDateString('ru-RU');
    const users=[...new Set(log.map(x=>x.name).filter(Boolean))].sort();
    const acts=[...new Set(log.map(x=>x.act).filter(Boolean))].sort();
    $('#shBody').innerHTML=`
      ${r.degraded?`<div class="note" style="border-color:rgba(232,177,96,.35);color:var(--warn)"><b>Журнал работает в защищённом режиме.</b><br>${esc(r.warning||'Архив KV временно недоступен, новые события продолжают фиксироваться.')}</div>`:''}
      <div class="audit-hero">
        <div><u>Событий</u><b>${log.length}</b><i>последние записи</i></div>
        <div><u>Сегодня</u><b>${log.filter(x=>new Date(x.at).toLocaleDateString('ru-RU')===todayKey).length}</b><i>действий</i></div>
        <div><u>Пользователи</u><b>${users.length}</b><i>в журнале</i></div>
      </div>
      <div class="audit-toolbar">
        <input class="inp" id="auditQ" placeholder="Поиск: заявка, клиент, действие…">
        <select class="inp" id="auditUser"><option value="">Все пользователи</option>${users.map(x=>`<option>${esc(x)}</option>`).join('')}</select>
        <select class="inp" id="auditAct"><option value="">Все действия</option>${acts.map(x=>`<option>${esc(x)}</option>`).join('')}</select>
      </div>
      <div id="auditList"></div>
      <div class="audit-foot">Источник: ${r.source==='recent-index'?'быстрый индекс':'серверный журнал'} · хранение до 180 дней</div>`;
    const renderAudit=()=>{
      const q=norm($('#auditQ')?.value||''), user=$('#auditUser')?.value||'', act=$('#auditAct')?.value||'';
      const arr=log.filter(x=>(!user||x.name===user)&&(!act||x.act===act)&&(!q||norm([x.act,x.entity,x.id,x.name,x.info].join(' ')).includes(q)));
      const day=d=>new Date(d).toLocaleDateString('ru-RU');
      const time=d=>new Date(d).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
      let html='',last='';
      arr.forEach(x=>{
        const d=day(x.at); if(d!==last){html+=`<div class="sec audit-day">${d}</div>`;last=d;}
        const tone=x.act==='удалил'||x.act==='неудачный вход'?'red':(x.act.includes('создал')||x.act.includes('вош')?'ok':(x.act.includes('оплат')?'warn':'acc'));
        html+=`<div class="audit-row ${tone}"><span class="audit-dot"></span><div class="audit-main"><b>${esc(x.act)}</b><span>${esc(x.entity)}${x.id?' · '+esc(x.id):''}</span><i>${esc(x.name)}${x.info?' · '+esc(x.info):''}</i></div><time>${time(x.at)}</time></div>`;
      });
      $('#auditList').innerHTML=html||'<div class="empty"><b>Ничего не найдено</b><span>Измените фильтр или поисковый запрос</span></div>';
    };
    ['auditQ','auditUser','auditAct'].forEach(id=>$('#'+id)?.addEventListener(id==='auditQ'?'input':'change',renderAudit));
    renderAudit();
  }catch(e){ $('#shBody').innerHTML='<div class="empty err"><b>Не удалось загрузить журнал</b><span>'+esc(String(e.message||e))+'</span></div>'; }
}

/* ---------- ЗАГРУЗКА ОСТАТКОВ ---------- */
function pickStock(){
  if(!isAdmin()){ toast('Остатки обновляет только администратор'); return; }
  const i=document.createElement('input'); i.type='file'; i.accept='.xls,.xlsx,.csv,.txt';
  i.onchange=()=>i.files[0]&&readStock(i.files[0]); i.click();
}
async function readStock(f){
  if(!isAdmin()){ toast('Недостаточно прав'); return; }
  toast('Читаю файл…');
  try{
    let text;
    const ext=f.name.split('.').pop().toLowerCase();
    if(ext==='csv'||ext==='txt') text=await f.text();
    else{ await loadXLSX(); const wb=XLSX.read(await f.arrayBuffer(),{type:'array',codepage:1251});
      text=XLSX.utils.sheet_to_csv(wb.Sheets[wb.SheetNames[0]],{FS:';'}); }
    const p=parseStock(text);
    if(!p.count){ toast('Не удалось разобрать файл'); return; }
    DB.stock={date:p.date||new Date().toLocaleDateString('ru-RU'),map:p.map,at:Date.now()};
    save(); recalcUsed(); render();
    /* Раньше «Остатки обновлены» показывалось сразу, не дожидаясь реальной записи
       на сервер — если запись не проходила, никто об этом не узнавал, и при
       следующем обновлении с сервера свежие остатки тихо откатывались назад. */
    try{
      await enqueue('stock.set',{stock:DB.stock});
      toast(`Остатки обновлены: ${p.count} позиций`);
    }catch(e){
      toast('Остатки сохранены на этом устройстве, но не отправлены в общую базу: '+String(e&&e.message||e).slice(0,90));
    }
  }catch(e){ toast('Ошибка чтения. Нужен интернет для разбора .xls'); }
}
/* Библиотеки подгружаются только когда действительно нужны */
function loadScript(src){
  return new Promise((ok,no)=>{ const s=document.createElement('script');
    s.src=src; s.onload=ok; s.onerror=()=>no(new Error('не загрузилось: '+src));
    document.head.appendChild(s); });
}
async function loadPDF(){
  if(window.jspdf&&window.jspdf.jsPDF) return;
  try{ await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'); }
  catch(e){ await loadScript('https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js'); }
  if(!window.jspdf||!window.jspdf.jsPDF) throw new Error('библиотека PDF не загрузилась');
}
/* Формирует настоящий .pdf с кириллицей (шрифт вшит в приложение) */
async function makePDF(o){
  await loadPDF();
  const { jsPDF }=window.jspdf;
  const doc=new jsPDF({unit:'mm',format:'a4'});
  doc.addFileToVFS('AgentSans.ttf',PDF_FONT_REG);
  doc.addFont('AgentSans.ttf','AgentSans','normal');
  doc.addFileToVFS('AgentSansB.ttf',PDF_FONT_BOLD);
  doc.addFont('AgentSansB.ttf','AgentSans','bold');
  const L=15, R=195, W=R-L;
  let y=16;
  const txt=(s,x,yy,{size=9,bold=false,align='left',color=[30,30,30],max=0}={})=>{
    doc.setFont('AgentSans',bold?'bold':'normal'); doc.setFontSize(size); doc.setTextColor(...color);
    /* массив строк передаём как есть: String([...]) склеил бы их запятыми в одну длинную строку */
    const v=Array.isArray(s)?s:String(s==null?'':s);
    doc.text((max&&!Array.isArray(v))?doc.splitTextToSize(v,max):v,x,yy,{align});
  };
  /* Гарантия, что строка физически влезает в свою колонку */
  const fit=(text,w,size)=>{
    doc.setFont('AgentSans','normal'); doc.setFontSize(size);
    let lines=doc.splitTextToSize(String(text||''),w);
    if(lines.length>2) lines=lines.slice(0,2);
    return lines.map((ln,i)=>{
      let s=ln;
      const tail=(i===1&&lines.length===2)?'…':'';
      while(s.length>1&&doc.getTextWidth(s+tail)>w) s=s.slice(0,-1);
      return s+((i===1&&s!==ln)?'…':'');
    });
  };
  const line=(yy,w=0.2,c=190)=>{ doc.setDrawColor(c); doc.setLineWidth(w); doc.line(L,yy,R,yy); };

  txt('Trade Agent Manager',L,y,{size:9,bold:true,color:[140,150,70]});
  txt(CFG.КОМПАНИЯ,R,y,{size:8,align:'right',color:[110,110,110]});
  y+=7;
  txt('Заказ '+o.no+(o.rev?'  (переделка '+o.rev+')':''),L,y,{size:16,bold:true,color:[20,20,20]});
  y+=6; line(y); y+=6;

  const u=DB.users[o.uid]||{};
  const info=[['Клиент',o.client||'—'],['Телефон',o.phone||'—'],
    ['Менеджер',u.name||o.uid],['Водитель',o.driver||'—'],
    ['Оплата',o.payType+(o.payDays?', '+o.payDays+' дней':' при отгрузке')],
    ['Отгрузка',ruDate(o.shipDate)],['Забрать деньги',o.payDays?ruDate(MONEY.dueOf(o)):'—']];
  info.forEach((row,i)=>{
    const x=i%2?L+W/2:L, yy=y+Math.floor(i/2)*5.5;
    txt(row[0],x,yy,{size:7.5,color:[130,130,130]});
    txt(row[1],x+26,yy,{size:9,bold:true,max:W/2-28});
  });
  y+=Math.ceil(info.length/2)*5.5+4;
  if(o.note){ txt('Комментарий: '+o.note,L,y,{size:8.5,color:[80,80,80],max:W}); y+=6; }

  const withDisc=(o.items||[]).some(i=>i.disc>0&&!i.bonus);
  /* Колонки заданы как непересекающиеся отрезки. Числа прижаты к правому краю
     своей колонки, название переносится строго внутри своей ширины. */
  const cols = withDisc
    ? [{t:'Арт.',      x:L,      w:17},
       {t:'Наименование',x:L+18,  w:54},
       {t:'Кол',       x:L+85,   w:9,  r:true},
       {t:'Без скидки',x:L+111,  w:20, r:true},
       {t:'Скидка',    x:L+127,  w:12, r:true},
       {t:'Цена',      x:L+152,  w:20, r:true},
       {t:'Сумма',     x:R,      w:22, r:true}]
    : [{t:'Арт.',      x:L,      w:20},
       {t:'Наименование',x:L+22,  w:82},
       {t:'Кол',       x:L+118,  w:10, r:true},
       {t:'Цена',      x:L+150,  w:22, r:true},
       {t:'Сумма',     x:R,      w:24, r:true}];
  const head=()=>{
    cols.forEach(c=>txt(c.t,c.x,y,{size:6.8,bold:true,color:[120,120,120],align:c.r?'right':'left'}));
    y+=4.2; line(y,0.3,150); y+=4.4;
  };
  line(y-2,0.4,120); y+=3; head();

  (o.items||[]).forEach((i,idx)=>{
    /* размер шрифта ставим ДО расчёта переноса, иначе строка получается шире колонки */
    const nm=fit(i.n,cols[1].w,8.3);   // не больше двух строк
    const rowH=Math.max(5.4,nm.length*3.9)+1.8;
    if(y+rowH>274){ doc.addPage(); y=18; head(); }
    txt(i.bonus?'бонус':i.a,cols[0].x,y,{size:7.6,color:i.bonus?[150,110,40]:[90,90,90]});
    txt(nm,cols[1].x,y,{size:8.3});
    const vals = withDisc
      ? [[String(i.q),2],[i.bonus?'—':money(i.base),3],[i.bonus?'—':Math.round(i.disc*100)+'%',4],
         [i.bonus?'—':money(i.price),5],[i.bonus?'БОНУС':money(i.sum),6]]
      : [[String(i.q),2],[i.bonus?'—':money(i.price),3],[i.bonus?'БОНУС':money(i.sum),4]];
    vals.forEach(([v,ci])=>txt(v,cols[ci].x,y,{size:8.3,align:'right',bold:ci===cols.length-1}));
    y+=rowH;
    doc.setDrawColor(228); doc.setLineWidth(0.1); doc.line(L,y-2.4,R,y-2.4);
  });

  y+=3; if(y>250){doc.addPage();y=20;}
  const T=MONEY.totals(o.items||[]), paid=MONEY.paid(o), debt=MONEY.debt(o), over=MONEY.over(o);
  const bq=(o.items||[]).filter(i=>i.bonus).reduce((s,i)=>s+(+i.q||0),0);
  const rows=[];
  if(bq) rows.push(['В том числе бонусом',bq+' шт']);
  (o.plan||[]).forEach((x,k)=>rows.push(['Платёж '+(k+1)+' · '+ruDate(x.d),money(x.s)]));
  if(T.totalBase>T.total){ rows.push(['Без скидки',money(T.totalBase)]); rows.push(['Скидка','−'+money(T.saving)]); }
  rows.push(['ИТОГО',money(T.total)+' '+CFG.ВАЛЮТА]);
  const ret=MONEY.returned(o);
  if(ret){ rows.push(['Возвращено','−'+money(ret)]); rows.push(['К оплате',money(MONEY.net(o))]); }
  if(paid) rows.push(['Оплачено',money(paid)]);
  if(debt) rows.push(['Долг',money(debt)+' '+CFG.ВАЛЮТА]);
  if(over) rows.push(['Переплата',money(over)]);
  rows.forEach((r,i)=>{
    const big=r[0]==='ИТОГО';
    if(big){ line(y,0.5,60); y+=5.5; }
    txt(r[0],L+W/2,y,{size:big?10:8.5,bold:big,color:big?[20,20,20]:[110,110,110]});
    txt(r[1],R,y,{size:big?13:9,bold:true,align:'right'});
    y+=big?7:5;
  });
  y+=14;
  txt('Отпустил  ____________________',L,y,{size:8.5,color:[110,110,110]});
  txt('Принял  ____________________',L+W/2,y,{size:8.5,color:[110,110,110]});
  return doc;
}
function auditEvent23(act,entity='система',id='',info=''){try{enqueue('audit.event',{act,entity,id,info})}catch(_){}}
async function savePDF(o){
  try{ toast('Готовлю PDF…'); const doc=await makePDF(o); doc.save(o.no+'.pdf'); auditEvent23('открыл PDF','заявка',o.no,o.client||''); toast('PDF сохранён'); return true; }
  catch(e){ toast('Не удалось сделать PDF: '+String(e.message||e).slice(0,60)); return false; }
}
/* Настоящий .xlsx для Excel */
async function saveXLSX(name,sheets){
  await loadXLSX();
  const wb=XLSX.utils.book_new();
  sheets.forEach(s=>{
    const ws=XLSX.utils.aoa_to_sheet(s.rows);
    ws['!cols']=(s.rows[0]||[]).map((_,i)=>({wch:Math.min(46,Math.max(10,
      ...s.rows.slice(0,200).map(r=>String(r[i]==null?'':r[i]).length+2)))}));
    XLSX.utils.book_append_sheet(wb,ws,s.name.slice(0,31));
  });
  XLSX.writeFile(wb,name,{bookType:'xlsx',compression:true}); auditEvent23('выгрузил Excel','файл',name,'');
}
function loadXLSX(){
  if(window.XLSX) return Promise.resolve();
  return loadScript('https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js')
    .catch(()=>loadScript('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js'));
}

/* ---------- ЭКСПОРТ ЗАКАЗНИКА ---------- */
function orderText(o){
  const L=[`ЗАКАЗ ${o.no}${o.rev?' (переделка '+o.rev+')':''}`,CFG.КОМПАНИЯ,
    `Менеджер: ${DB.users[o.uid]?.name||o.uid}`,`Клиент: ${o.client}`];
  if(o.phone)L.push(`Тел: ${o.phone}`);
  L.push(`Отгрузка: ${ruDate(o.shipDate)}${o.driver?' · водитель '+o.driver:''}`);
  L.push(o.payDays?`Оплата: ${o.payType}, ${o.payDays} дн → деньги до ${ruDate(MONEY.dueOf(o))}`
                  :`Оплата: ${o.payType} при отгрузке`,'');
  const paidItems=(o.items||[]).filter(i=>!i.bonus), bonusItems=(o.items||[]).filter(i=>i.bonus);
  paidItems.forEach((i,k)=>L.push(`${k+1}. ${i.a} — ${i.n}\n   ${i.q} шт × ${money(i.price)}`+
    (i.disc>0?` (было ${money(i.base)}, −${Math.round(i.disc*100)}%)`:'')+` = ${money(i.sum)}`));
  if(bonusItems.length){ L.push('','БОНУС (без оплаты):');
    bonusItems.forEach(i=>L.push(`   ${i.n} — ${i.q} шт`)); }
  L.push('');
  if(o.plan&&o.plan.length){ L.push('','График платежей:');
    o.plan.forEach(x=>L.push(`   ${ruDate(x.d)} — ${money(x.s)} ${CFG.ВАЛЮТА}`)); L.push(''); }
  if(o.totalBase>o.total){ L.push(`Без скидки: ${money(o.totalBase)} ${CFG.ВАЛЮТА}`,
    `Скидка: −${money(o.totalBase-o.total)} ${CFG.ВАЛЮТА}`); }
  L.push(`ИТОГО: ${money(o.total)} ${CFG.ВАЛЮТА}`);
  if(o.note)L.push('',`Комментарий: ${o.note}`);
  return L.join('\n');
}
function orderRows(o){
  const T=MONEY.totals(o.items||[]), withDisc=T.totalBase>T.total, u=DB.users[o.uid]||{};
  const rows=[['Trade Agent Manager · заказ',o.no],['Дата отгрузки',ruDate(o.shipDate)],['Менеджер',u.name||o.uid],
    ['Клиент',o.client],['Телефон',o.phone||''],['Водитель',o.driver||''],
    ['Тип оплаты',o.payType],['Срок оплаты, дней',o.payDays||0],
    ['Забрать деньги',o.payDays?ruDate(MONEY.dueOf(o)):''],['Комментарий',o.note||''],[]];
  rows.push(withDisc?['Артикул','Наименование','Кол-во','Без скидки','Скидка %','Цена','Сумма']
                    :['Артикул','Наименование','Кол-во','Цена','Сумма']);
  (o.items||[]).forEach(i=>rows.push(withDisc
    ? [i.a,i.n,i.q,i.base,Math.round(i.disc*100),i.price,i.sum]
    : [i.a,i.n,i.q,i.price,i.sum]));
  rows.push([]);
  if(withDisc){ rows.push(['','','','','','Без скидки',T.totalBase]);
                rows.push(['','','','','','Скидка',-T.saving]); }
  rows.push(['','','','','','ИТОГО',T.total]);
  const paid=MONEY.paid(o), debt=MONEY.debt(o);
  if(paid) rows.push(['','','','','','Оплачено',paid]);
  if(debt) rows.push(['','','','','','Долг',debt]);
  return rows;
}
