/* Номер оператора в международном формате: 8XXXXXXXXXX и +7XXXXXXXXXX → 7XXXXXXXXXX */
function waNumber(){
  let n=String((DB.settings&&DB.settings.waOperator)||'').replace(/\D/g,'');
  if(!n) return '';
  if(n.length===10&&n[0]==='7') n='7'+n;          // 7011234567
  if(n.length===11&&n[0]==='8') n='7'+n.slice(1); // 87011234567
  return n;
}
