/* Забирает свежий файл приложения. Данные не трогает: они привязаны к адресу сайта. */
async function hardReload(targetVer=''){
  try{ if(window.caches){ const ks=await caches.keys(); await Promise.all(ks.map(k=>caches.delete(k))); } }catch(e){}
  try{ if(navigator.serviceWorker){ const rs=await navigator.serviceWorker.getRegistrations();
    await Promise.all(rs.map(r=>r.unregister())); } }catch(e){}
  const v=String(targetVer||NEWVER||Date.now());
  const url=location.pathname+'?app='+encodeURIComponent(v)+'&refresh='+Date.now();
  try{ location.replace(url); }catch(_){ location.href=url; }
}

function dl(name,text){
  const b=new Blob([text],{type:'text/csv;charset=utf-8'}),u=URL.createObjectURL(b),a=document.createElement('a');
  a.href=u;a.download=name;document.body.appendChild(a);a.click();
  setTimeout(()=>{URL.revokeObjectURL(u);a.remove()},500);
}

/* Постоянная ссылка на бланк заказа. Ключ хранится в самой заявке,
   поэтому подобрать чужой документ нельзя. */
function docKeyOf(o){
  if(!o.docKey){ o.docKey=uid()+uid().slice(0,6); o.updatedAt=Date.now();
    save(); enqueue('order.save',{order:o}); }
  return o.docKey;
}
function docLink(o){
  /* Public server document links were a Cloudflare feature. Firebase build shares the generated PDF instead. */
  return '';
}
async function shareOrder(o){
  /* Уходит ТОЛЬКО файл: ни текста, ни ссылки, ни заголовка.
     Система показывает выбор контакта, дальше PDF отправляется как документ. */
  let doc=null;
  try{
    toast('Готовлю PDF…');
    doc=await makePDF(o);
  }catch(e){
    toast('Не удалось собрать PDF: '+String(e.message||e).slice(0,60));
    return;
  }
  try{
    const blob=doc.output('blob');
    const file=new File([blob],o.no+'.pdf',{type:'application/pdf'});
    if(navigator.canShare&&navigator.canShare({files:[file]})&&navigator.share){
      await navigator.share({files:[file]});     // без text, title и url
      auditEvent23('отправил оператору','заявка',o.no,o.client||'');
      return;
    }
  }catch(e){
    if(e&&(e.name==='AbortError'||e.name==='NotAllowedError')) return;  // закрыли окно
  }
  /* Веб-браузер не умеет прикрепить PDF прямо к заданному WhatsApp-контакту без WhatsApp Business API.
     Поэтому безопасный fallback: сохраняем PDF и сразу открываем настроенный чат оператора. */
  try{
    doc.save(o.no+'.pdf');
    const n=waNumber();
    if(n){
      const txt=encodeURIComponent('Заказ '+o.no+' — PDF сохранён на устройстве. Прикрепите файл '+o.no+'.pdf');
      window.open('https://wa.me/'+n+'?text='+txt,'_blank','noopener');
      auditEvent23('отправил оператору','заявка',o.no,o.client||''); toast('PDF сохранён, чат оператора открыт');
    } else toast('PDF в «Загрузках» — укажите номер оператора в Админке');
  }catch(e){ toast('Не удалось сохранить PDF'); }
}


/* ---------- СВЯЗЬ С СЕРВЕРОМ ---------- */
const FALLBACK_API='https://tradeagent-manager-api.87058608077a.workers.dev';
const API_HOST='tradeagent-manager-api.87058608077a.workers.dev';
/* Manager v24.2.8: рабочая база только Cloudflare API. Старые Google Apps Script
   и прежние orderagent/orderagent-api больше не принимаются как sync endpoint. */
const SYNC_OK=/^https:\/\/tradeagent-manager-api\.87058608077a\.workers\.dev\/?$/i;
const UNIFIED_MODE=/^https:$/i.test(location.protocol||'')&&(location.hostname||'').toLowerCase()===API_HOST;
const DEFAULT_API=FALLBACK_API;
let SYNCING=false, DIRTY=false, FLUSHING=false, BACKOFF=0, REV=-1;
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,10);
const online=()=>typeof navigator==='undefined'||navigator.onLine!==false;
let OFFLINE_LOGIN_READY=null;
let LIVE_WS=null, LIVE_RECONNECT=null, LIVE_PUSH=false, LIVE_PING=null, LIVE_BACKOFF=1000;
let NET_FAILS=0, LAST_NET_OK=0, LAST_PROBE=0;

function guessSyncUrl(){
  if(UNIFIED_MODE) return location.origin;
  return DB.sync.url||FALLBACK_API;
}
function persist(){ try{ localStorage.setItem(KEY,JSON.stringify(DB)); }catch(e){} }

async function fetchTimed(url,opts={},ms=5500){
  const c=new AbortController(), t=setTimeout(()=>c.abort(),ms);
  try{
    const r=await fetch(url,Object.assign({},opts,{signal:c.signal,cache:'no-store'}));
    LAST_NET_OK=Date.now(); NET_FAILS=0; return r;
  }catch(e){
    NET_FAILS++;
    if(e&&e.name==='AbortError') throw Object.assign(new Error('сервер не ответил вовремя'),{code:'TIMEOUT'});
    throw Object.assign(new Error(String(e&&e.message||e||'ошибка сети')),{code:'NETWORK'});
  }finally{ clearTimeout(t); }
}
function syncCandidates(){
  /* Единственный допустимый источник истины Manager — новый Cloudflare API. */
  return [DEFAULT_API];
}
async function probeServer(base,ms=3200){
  try{
    const r=await fetchTimed(base.replace(/\/+$/,'')+'/ping?ts='+Date.now(),{},ms);
    const j=await r.json().catch(()=>null);
    if(j&&j.ok===true) return {ok:true,url:base.replace(/\/+$/,''),data:j,http:r.status};
    return {ok:false,url:base,error:(j&&j.error)||('HTTP '+r.status),code:(j&&j.code)||'HTTP',http:r.status};
  }catch(e){return {ok:false,url:base,error:String(e.message||e),code:e.code||'NETWORK'}}
}
async function recoverServer(force=false){
  /* Автоматически переводим старые установки с Google Apps Script / orderagent-api
     на единственный актуальный API, даже если в localStorage остался старый URL. */
  if(DB.sync.url!==DEFAULT_API){
    DB.sync.url=DEFAULT_API; DB.sync.err=''; DB.sync.code=''; DB.sync.at=0; persist();
  }
  const now=Date.now();
  if(!force&&now-LAST_PROBE<5000&&!DB.sync.err) return {ok:true,url:DEFAULT_API,cached:true};
  LAST_PROBE=now;
  const hit=await probeServer(DEFAULT_API,3200);
  if(hit.ok){DB.sync.url=DEFAULT_API;DB.sync.err='';DB.sync.code='';persist();return hit;}
  return hit||{ok:false,error:'сервер CRM не найден',code:'NETWORK'};
}
async function api(path,{method='GET',body,auth=true,retry=true,timeout=6500}={}){
  if(!DB.sync.url) throw Object.assign(new Error('база не подключена'),{code:'OFF'});
  const h={'Content-Type':'application/json'};
  if(auth&&DB.auth.token) h['Authorization']='Bearer '+DB.auth.token;
  const call=async()=>{
    const r=await fetchTimed(DB.sync.url.replace(/\/+$/,'')+path,{method,headers:h,body:body?JSON.stringify(body):undefined},timeout);
    let j=null;try{j=await r.json()}catch(e){}
    if(!j) throw Object.assign(new Error('сервер CRM ответил не по формату'),{code:'BAD'});
    if(!r.ok&&j.code==='AUTH'){
      DB.auth={token:'',exp:0,uid:''};persist();
      if(ME&&typeof relogin==='function') setTimeout(()=>relogin('Сессия завершена — войдите снова'),50);
    }
    if(!r.ok) throw Object.assign(new Error(j.error||('ошибка '+r.status)),{code:j.code||'HTTP',status:r.status});
    DB.sync.err='';DB.sync.code='';LAST_NET_OK=Date.now();NET_FAILS=0;return j;
  };
  try{return await call()}
  catch(e){
    if(retry&&['NETWORK','TIMEOUT'].includes(e.code)){
      const r=await recoverServer(true);
      if(r.ok) return api(path,{method,body,auth,retry:false,timeout});
    }
    throw e;
  }
}

/* ---------- проверка пароля без интернета ---------- */
const LOCAL_PBKDF2=100000;
async function pbkdf2(pass,salt,iterations=LOCAL_PBKDF2){
  const enc=new TextEncoder();
  const k=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveBits']);
  const b=await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations,hash:'SHA-256'},k,256);
  return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');
}
async function rememberLocal(id,pass){
  try{ const salt=uid(); DB.local[id]={salt,iter:LOCAL_PBKDF2,hash:await pbkdf2(pass,salt,LOCAL_PBKDF2)}; persist(); }catch(e){}
}
async function checkLocal(id,pass){
  const l=DB.local[id]; if(!l) return null;
  try{
    const it=Math.max(10000,+l.iter||10000), ok=(await pbkdf2(pass,l.salt,it))===l.hash;
    if(ok&&it<LOCAL_PBKDF2) await rememberLocal(id,pass);
    return ok;
  }catch(e){ return null; }
}


