/* ---------- очередь изменений ---------- */
function enqueue(type,payload){
  DB.queue.push(Object.assign({opId:uid(),type,at:Date.now(),tries:0},payload));
  save();
  flush().then(sent=>{ if(sent) pull(); });   // отправили — сразу забираем общий результат
}
function pending(){ return DB.queue.length; }
async function flush(loud){
  if(FLUSHING||!DB.sync.url||!DB.auth.token||!DB.queue.length) return false;
  if(!online()){ paintSync(); return false; }
  if(BACKOFF>Date.now()) return false;
  FLUSHING=true; paintSync();
  try{
    const batch=DB.queue.slice(0,50);
    const sentAny=batch.length>0;
    const res=await api('/push',{method:'POST',body:{
      ops:batch, schemaVersion:SCHEMA,
      presence:{ver:VERSION,dev:(navigator.userAgent||'').slice(0,40)}}});
    const done=new Set(), rejected=[];
    const byOp=new Map(batch.map(op=>[op.opId,op]));
    const putOrder=o=>{ if(!o||!o.id)return; const i=DB.orders.findIndex(x=>x.id===o.id); if(i>=0)DB.orders[i]=o; else DB.orders.unshift(o); };
    (res.results||[]).forEach(x=>{
      if(x.order) putOrder(x.order);
      if(x.ok||x.repeated||x.skipped){ done.add(x.opId); return; }
      if(x.error){
        done.add(x.opId); rejected.push(x);
        const op=byOp.get(x.opId);
        if(x.current) putOrder(x.current);
        else if(op&&op.type==='order.save'&&op.order&&!op.order.serverUpdatedAt)
          DB.orders=DB.orders.filter(o=>o.id!==op.order.id); // новая заявка сервером не принята
        console.warn('операция отклонена:',x.code,x.error);
      }
    });
    if(rejected.length){
      DB.failedOps=(DB.failedOps||[]).concat(rejected.map(x=>({at:Date.now(),code:x.code||'',error:x.error||'',opId:x.opId}))).slice(-30);
      const first=rejected[0]; DB.sync.err='Отклонено сервером: '+first.error; DB.sync.code=first.code||'REJECTED';
      toast(DB.sync.err.slice(0,160));
    }
    const wasLen=DB.queue.length;
    DB.queue=DB.queue.filter(o=>!done.has(o.opId));
    if(!rejected.length){ DB.sync.err=''; DB.sync.code=''; } DB.sync.at=Date.now(); BACKOFF=0;
    if(res.rev!=null) REV=res.rev;
    persist();
    if(DB.queue.length&&DB.queue.length<wasLen){   // за время отправки добавились новые — досылаем
      FLUSHING=false; return flush(loud);
    }
    if(!DB.queue.length&&loud) toast('Все изменения отправлены');
    /* Сразу забираем общий результат: свои же остатки должны обновиться
       не через четыре секунды, а мгновенно. */
    if(sentAny) setTimeout(()=>pull(),0);
    return sentAny;
  }catch(e){
    DB.queue.forEach(o=>{ if(o.tries!=null) o.tries++; });
    DB.sync.err=String(e.message||e).slice(0,120); DB.sync.code=e.code||'';
    BACKOFF=Date.now()+Math.min(60000,3000*Math.pow(2,Math.min(4,(DB.queue[0]&&DB.queue[0].tries)||1)));
    persist();
    if(loud) toast('Не отправилось: '+DB.sync.err);
  }finally{ FLUSHING=false; paintSync(); }
  return false;
}

/* ---------- приём изменений ---------- */
function dataSig(){
  let s=0; for(const o of DB.orders) s+=(o.updatedAt||0)%1e7;
  return DB.orders.length+':'+s+':'+(DB.stock.at||0)+':'+(DB.usersAt||0)+':'+(DB.photosAt||0)+':'+
    JSON.stringify(DB.settings||{});
}
function safeToRender(){
  if(VIEW==='cart') return false;                                   // форма заказа — не трогаем
  if($('#sheet').classList.contains('on')||$('#docView').classList.contains('on')) return false;
  return true;
}
function applyIfSafe(changed){
  if(!changed) return;
  if(safeToRender()){ DIRTY=false; render(); } else { DIRTY=true; paintSync(); }
}
function clampDraft(){
  const d=DB.drafts[ME&&ME.id]; if(!d) return false;
  let cut=false;
  for(const a in d.items){ const max=stockOf(a);
    if(d.items[a]>max){ cut=true; if(max>0) d.items[a]=max; else { delete d.items[a]; delete d.prices[a]; } } }
  for(const k in (d.bonus||{})){ const max=stockOf(k);
    if(d.bonus[k]>max){ cut=true; if(max>0) d.bonus[k]=max; else delete d.bonus[k]; } }
  if(cut) toast('Часть позиций разобрали — количество в заказе уменьшено');
  return cut;
}
let PULLAGAIN=false;
async function pull(loud){
  if(!DB.sync.url||!DB.auth.token) return;
  /* Если обмен уже идёт, не теряем запрос, а повторяем его после завершения —
     иначе свежие остатки могли не примениться сразу после своей же заявки. */
  if(SYNCING){ PULLAGAIN=true; return; }
  SYNCING=true; paintSync(); syncPulse();
  const before=dataSig();
  let photosUpdated=false;
  try{
    const rm=await api('/pull?since='+(DB.since||0));
    if(!Array.isArray(rm.orders)) throw new Error('сервер вернул не те данные');
    if(rm.schemaVersion&&rm.schemaVersion>SCHEMA){
      throw new Error('сервер новее приложения — обновите приложение (значок с инициалами → Проверить обновление)'); }
    if(rm.schemaVersion&&rm.schemaVersion<SCHEMA){
      throw new Error('на сервере старая версия — обновите Worker TradeAgent Manager'); }
    Object.keys(rm.deleted||{}).forEach(id=>{ DB.deleted[id]=Math.max(DB.deleted[id]||0, rm.deleted[id]||0); });
    const by={}; DB.orders.forEach(o=>by[o.id]=o);
    rm.orders.forEach(o=>{ const l=by[o.id]; if(!l||(o.updatedAt||0)>(l.updatedAt||0)) by[o.id]=o; });
    DB.orders=Object.values(by)
      .filter(o=>!(DB.deleted[o.id]>=(o.updatedAt||0)))
      .sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));
    if(rm.stock && !DB.queue.some(o=>o.type==='stock.set')){
      /* Server is authoritative for stock. Never keep a stale local snapshot merely
         because this device has a newer local timestamp/clock. */
      DB.stock=rm.stock;
    }
    (rm.users||[]).forEach(u=>{
      const l=DB.users[u.id]||{};
      DB.users[u.id]=Object.assign({},l,{id:u.id,name:u.name,role:u.role,hasPass:u.hasPass,mustChange:u.mustChange,pay:u.pay,freePrice:u.freePrice,seeDisc:u.seeDisc,at:u.at});
      delete DB.users[u.id].pass;                       // пароли на устройстве не хранятся
    });
    if(ME&&DB.users[ME.id]) ME=DB.users[ME.id];
    Object.keys(rm.seq||{}).forEach(k=>{ DB.seq[k]=Math.max(DB.seq[k]||0, rm.seq[k]||0); });
    DB.presence=rm.presence||DB.presence;
    if(rm.settings&&!DB.queue.some(o=>o.type==='settings.set'))
      DB.settings=Object.assign({},DB.settings,rm.settings);
    if(rm.photos&&typeof rm.photos==='object'&&rm.photos.map&&typeof rm.photos.map==='object'){
      const nextPhotos=Object.assign({},rm.photos.map);
      const nextPhotosAt=Number(rm.photos.at)||Date.now();
      const prevPhotos=DB.photos||{};
      photosUpdated=nextPhotosAt!==(DB.photosAt||0) ||
        Object.keys(nextPhotos).length!==Object.keys(prevPhotos).length ||
        Object.keys(nextPhotos).some(k=>nextPhotos[k]!==prevPhotos[k]);
      /* Server is authoritative for shared photos too. */
      DB.photos=nextPhotos;
      DB.photosAt=nextPhotosAt;
    }
    if(rm.used&&typeof rm.used==='object') DB.usedSrv=rm.used;
    if(rm.needsOrderIndex&&isAdmin()&&DB.orders&&DB.orders.length&&!DB._indexSeedQueued){
      DB._indexSeedQueued=Date.now();
      DB.queue.push({opId:uid(),type:'index.seed',orders:DB.orders.map(o=>({id:o.id,uid:o.uid,updatedAt:o.updatedAt||0})),deleted:Object.assign({},DB.deleted||{}),seq:Object.assign({},DB.seq||{}),at:Date.now(),tries:0});
    }
    if(rm.rev!=null) REV=rm.rev;
    if(rm.serverTime) DB.skew=rm.serverTime-Date.now();   // часы устройств расходятся
    /* Небольшое перекрытие окна защищает от eventual consistency Cloudflare KV. */
    DB.since=Math.max(0,(rm.serverTime||Date.now())-5*60*1000);
    DB.sync.err=''; DB.sync.code=''; DB.sync.at=Date.now();
    persist();
    recalcUsed(); const cut=clampDraft(); if(cut) persist();
    if(loud) toast('Связь есть — данные получены');
    const changed=dataSig()!==before||cut||loud;
    applyIfSafe(changed); if(photosUpdated&&VIEW==='price'&&typeof ta23PaintProducts==='function') ta23PaintProducts(); if(changed){syncPulse();setTimeout(markFreshCards,60);}
  }catch(e){
    DB.sync.err=String(e.message||e).slice(0,120); DB.sync.code=e.code||'';
    persist();
    if(loud) toast('Не подключилось: '+DB.sync.err);
  }finally{
    SYNCING=false; paintSync();
    if(PULLAGAIN){ PULLAGAIN=false; setTimeout(()=>pull(),0); }
  }
}
async function syncNow(loud){ await flush(loud); await pull(loud); }

/* ---------- обновление приложения: надежная проверка GitHub + Pages ---------- */
let NEWVER='';
let UPDATE_PUBLISHING='';
const UPDATE_REPO_URL='https://raw.githubusercontent.com/Arekenzi/TradeAgentManager/main/index.html';
function cmpVer(a,b){
  const A=String(a||'').split('.').map(x=>parseInt(x,10)||0), B=String(b||'').split('.').map(x=>parseInt(x,10)||0);
  for(let i=0;i<Math.max(A.length,B.length);i++){const d=(A[i]||0)-(B[i]||0);if(d)return d;}
  return 0;
}
async function fetchAppVersion(url){
  const sep=url.includes('?')?'&':'?';
  const r=await fetch(url+sep+'_ta_update='+Date.now(),{
    cache:'no-store',
    headers:{'Cache-Control':'no-cache','Pragma':'no-cache'}
  });
  if(!r.ok) throw new Error('HTTP '+r.status);
  const head=(await r.text()).slice(0,16000);
  const m=head.match(/name=["']app-version["']\s+content=["']([^"']+)["']/i)
       || head.match(/content=["']([^"']+)["']\s+name=["']app-version["']/i);
  return m?m[1]:'';
}
async function checkAppUpdate(manual=false){
  if(!/^https?:$/i.test(location.protocol||'')) return false;
  let repoVer='',pageVer='';
  try{ repoVer=await fetchAppVersion(UPDATE_REPO_URL); }catch(_){ }
  try{ pageVer=await fetchAppVersion(location.pathname); }catch(_){ }
  const remote=[repoVer,pageVer].filter(Boolean).sort((a,b)=>cmpVer(b,a))[0]||'';
  if(!remote){ if(manual)toast('Не удалось определить версию обновления'); return false; }
  if(cmpVer(remote,VERSION)<=0){
    NEWVER=''; UPDATE_PUBLISHING=''; paintSync();
    if(manual)toast('Установлена актуальная версия '+VERSION);
    return false;
  }
  /* Репозиторий уже новее, но Pages еще отдает старую сборку — не перезагружаем в старую версию. */
  if(repoVer && cmpVer(repoVer,VERSION)>0 && (!pageVer || cmpVer(pageVer,repoVer)<0)){
    NEWVER=''; UPDATE_PUBLISHING=repoVer; paintSync();
    if(manual)toast('Версия '+repoVer+' уже загружена. GitHub Pages еще публикует ее — повторите проверку через 30–60 сек.');
    return true;
  }
  UPDATE_PUBLISHING=''; NEWVER=remote; paintSync();
  if(manual) toast('Доступна версия '+remote+'. Нажмите статус «обновить».');
  return true;
}
/* ---------- честный статус ---------- */
/* txt — короткая метка для шапки, full — расшифровка на экране связи */
function syncState(){
  if(NEWVER) return {k:'wait',txt:'обновить',full:'Вышла версия '+NEWVER+'. Нажмите, чтобы обновить приложение.'};
  if(UPDATE_PUBLISHING) return {k:'wait',txt:'публикация',full:'Версия '+UPDATE_PUBLISHING+' уже в GitHub и ожидает публикации GitHub Pages.'};
  if(!DB.sync.url) return {k:'off',txt:'без базы',full:'Общая база не подключена.'};
  if(!DB.auth.token) return {k:'wait',txt:'локально',full:'Открыт локальный режим. Нажмите, чтобы подключиться к общей базе.'};
  if(FLUSHING||SYNCING) return {k:'wait',txt:'обмен',full:'Идёт защищённая синхронизация с CRM.'};
  if(pending()) return {k:'wait',txt:'↑ '+pending(),full:'Ожидают отправки: '+pending()+'. Они уйдут автоматически.'};
  if(DB.sync.err){
    const recent=DB.sync.at&&Date.now()-DB.sync.at<20000;
    return {k:recent?'wait':'err',txt:recent?'переподключение':'связь',full:'CRM временно недоступна: '+DB.sync.err+'. Приложение переподключается автоматически.'};
  }
  if(!DB.sync.at) return {k:'wait',txt:'подключение',full:'Устанавливаю связь с общей базой.'};
  return {k:'ok',txt:LIVE_PUSH?'LIVE':'онлайн',full:(LIVE_PUSH?'WebSocket LIVE активен. ':'CRM подключена. ')+
    'Последний обмен: '+new Date(DB.sync.at).toLocaleTimeString('ru-RU')};
}
function syncLink(){
  const b=btoa(encodeURIComponent(DB.sync.url)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
  return location.origin+location.pathname+'#s='+b;
}
function readSyncFromLink(){
  const m=(location.hash||'').match(/[#&]s=([^&]+)/); if(!m) return;
  try{
    let s=m[1].replace(/-/g,'+').replace(/_/g,'/'); while(s.length%4) s+='=';
    const url=decodeURIComponent(atob(s));
    if(SYNC_OK.test(url)&&url!==DB.sync.url){
      DB.sync={url,at:0,err:'',code:''}; persist();
      setTimeout(()=>toast('Общая база подключена'),600);
    }
  }catch(e){}
  try{ history.replaceState(null,'',location.pathname+location.search); }catch(e){}
}
async function autoConnect(){
  const r=await recoverServer(true);
  if(r&&r.ok){DB.sync.err='';DB.sync.code='';persist();return true}
  DB.sync.err=String(r&&r.error||'сервер CRM не найден').slice(0,120);DB.sync.code=(r&&r.code)||'NETWORK';persist();return false;
}

/* ---------- экран связи ---------- */
function syncAgo(){
  if(!DB.sync.at)return 'ещё не было'; const sec=Math.max(0,Math.round((Date.now()-DB.sync.at)/1000));
  if(sec<10)return 'только что'; if(sec<60)return sec+' сек назад'; const m=Math.round(sec/60); if(m<60)return m+' мин назад'; return Math.round(m/60)+' ч назад';
}
