/* Короткая подсказка при первом входе — один раз на устройство */
function firstHint(){
  if(DB.hintShown) return;
  DB.hintShown=1; persist();
  setTimeout(()=>{
    sheet('Как здесь работать',`
      <div class="note g">Три вещи, которых хватит на первый день.</div>
      <div class="card pad">
        <div style="font-size:14.5px;font-weight:700;margin-bottom:4px">1. Соберите заказ</div>
        <div style="font-size:13.5px;color:var(--mut);margin-bottom:14px">
          Вкладка «Каталог» → найдите товар → «Добавить в заказ».
          Кнопки +5 и +10 набирают быстрее. Внизу по центру появится сумма — нажмите её.</div>
        <div style="font-size:14.5px;font-weight:700;margin-bottom:4px">2. Отправьте оператору</div>
        <div style="font-size:13.5px;color:var(--mut);margin-bottom:14px">
          «Заявки» → нажмите на заявку → «Отправить оператору». Готовится PDF.</div>
        <div style="font-size:14.5px;font-weight:700;margin-bottom:4px">3. Следите за метками вверху</div>
        <div style="font-size:13.5px;color:var(--mut)">
          Слева дата остатков, справа связь с базой. «ок» — всё синхронно,
          «↑2» — есть неотправленное, нажмите на метку.</div>
        <div style="font-size:13px;color:var(--mut);margin-top:14px">
          Полный список возможностей: значок с инициалами вверху справа → «Все возможности».</div>
      </div>
      <div class="btns"><button class="btn pri" id="hintOk">Понятно, начать</button></div>`,
    el=>el.querySelector('#hintOk').addEventListener('click',closeSheet));
  },700);
}
function enterApp(){
  const login=$('#login'), app=$('#app');
  document.body.classList.add('authenticated');
  if(login){login.classList.add('hide');login.style.setProperty('display','none','important');login.setAttribute('aria-hidden','true');}
  if(app){app.classList.remove('hide');app.style.removeProperty('display');app.style.removeProperty('visibility');app.removeAttribute('aria-hidden');}
  $('#lPass').value=''; $('#lPass2').value='';
  recalcUsed(); go('home');
  /* Successful login must enter the workspace immediately. Network follow-up is non-blocking. */
  Promise.resolve().then(()=>syncNow()).catch(e=>{DB.sync.err=String(e&&e.message||e||'').slice(0,120);persist();paintSync();});
  firstHint();
}
async function doLogin(){
  const id=$('#lUser').value||'admin', pass=$('#lPass').value, btn=$('#lGo');
  OFFLINE_LOGIN_READY=null; $('#lOffline').classList.add('hide'); $('#lErr').textContent='';
  const normalLabel=()=>$('#lPass2').classList.contains('hide')?'Войти':'Сохранить и войти';
  let completed=false;
  const stopBusy=()=>{btn.disabled=false;btn.classList.remove('login-busy');btn.textContent=normalLabel();};
  const err=m=>{ $('#lErr').textContent=m; stopBusy(); };
  if(pass.length<4) return err('Минимум 4 знака');
  const setting=!$('#lPass2').classList.contains('hide');
  if(setting&&!/^\d{6}$/.test(pass)) return err('Новый код — 6 цифр');
  if(setting&&pass!==$('#lPass2').value) return err('Коды не совпадают');
  btn.disabled=true;btn.classList.add('login-busy');btn.textContent='Вхожу…';
  const watchdog=setTimeout(()=>{if(!completed){$('#lErr').textContent='Вход не завершился вовремя. Нажмите «Войти» ещё раз.';stopBusy()}},10000);
  try{
    if(UNIFIED_MODE){DB.sync.url=location.origin;DB.sync.err='';DB.sync.code='';persist()}
    else {const link=await recoverServer(true);if(!link.ok) throw Object.assign(new Error(link.error||'сервер CRM недоступен'),{code:link.code||'NETWORK'})}
    let r=await api('/login',{method:'POST',auth:false,retry:false,timeout:7000,body:{login:id,pass,bootstrapCode:BOOTSTRAP_CODE||undefined,dev:(navigator.userAgent||'').replace(/[();]/g,' ').slice(0,60)}});
    if(r.code==='BOOTSTRAP_REQUIRED'){
      const bc=prompt('Первый запуск. Введите ADMIN_BOOTSTRAP_CODE из Cloudflare.'); if(!bc) return err('Первичная настройка отменена');
      BOOTSTRAP_CODE=bc.trim();$('#lPass2').classList.remove('hide');$('#lsub').textContent='Первый запуск — придумайте код администратора из 6 цифр';$('#lPass').value='';$('#lPass2').value='';$('#lPass').placeholder='Новый код из 6 цифр';return err('Введите новый код и повторите его ниже');
    }
    if(r.code==='SET_PASSWORD'){
      if($('#lPass2').classList.contains('hide')){$('#lPass2').classList.remove('hide');$('#lsub').textContent='Первый вход — придумайте код из 6 цифр';$('#lPass').placeholder='Новый код из 6 цифр';return err('Придумайте код и повторите его ниже')}
      r=await api('/login',{method:'POST',auth:false,retry:false,timeout:7000,body:{login:id,newPass:pass,bootstrapCode:BOOTSTRAP_CODE||undefined,dev:(navigator.userAgent||'').replace(/[();]/g,' ').slice(0,60)}});
    }
    if(!r.ok||!r.token) return err(r.error||'Не удалось войти');
    DB.auth={token:r.token,exp:r.exp,uid:r.user.id};BOOTSTRAP_CODE='';BACKOFF=0;REV=-1;DB.queue.forEach(op=>{op.tries=0});DB.sync.err='';DB.sync.code='';DB.users[r.user.id]=Object.assign({},DB.users[r.user.id],r.user);delete DB.users[r.user.id].pass;ME=DB.users[r.user.id];persist();
    completed=true;clearTimeout(watchdog);stopBusy();enterApp();
    /* local offline credential is helpful, but must NEVER block a successful online login */
    rememberLocal(id,pass).catch(()=>{});
    if(r.user.mustChange||!/^\d{6}$/.test(pass)) setTimeout(()=>{
      const why=r.user.mustChange?'Временный код нужно заменить.':'Можно заменить прежний пароль на быстрый код.';
      if(confirm(why+' Установить новый код из 6 цифр сейчас?')){
        const np=prompt('Новый код из 6 цифр');
        if(np&&/^\d{6}$/.test(np)) api('/password',{method:'POST',body:{oldPass:pass,newPass:np}}).then(x=>{if(x.token){DB.auth.token=x.token;DB.auth.exp=x.exp;persist()}rememberLocal(id,np);DB.users[id].mustChange=false;persist();toast('Новый код установлен')}).catch(e=>toast('Не удалось: '+e.message));
        else if(np!==null) toast('Нужно ровно 6 цифр');
      }
    },900);
    return;
  }catch(e){
    if(e.status || !['NETWORK','TIMEOUT','OFF','BAD'].includes(e.code||'')) return err(e.message||'Сервер отклонил вход');
    if(e.code==='BAD') return err('Сервер ответил неправильно. Обновите страницу.');
    DB.sync.err=String(e.message||e).slice(0,120);persist();
    const okLocal=await checkLocal(id,pass);
    if(okLocal===true){OFFLINE_LOGIN_READY={id,pass};$('#lOffline').classList.remove('hide');return err('Сервер временно недоступен. Можно повторить вход или продолжить офлайн.')}
    if(okLocal===false) return err('Неверный код');
    return err(e.code==='TIMEOUT'?'Сервер отвечает слишком долго. Повторите вход.':'Не удалось связаться с сервером. Проверьте /ping.');
  }finally{
    if(!completed){clearTimeout(watchdog); if(btn.disabled) stopBusy();}
  }
}
/* Сессия кончилась или администратор сбросил код.
   Возвращаем на экран входа, НЕ теряя неотправленные изменения. */
function relogin(msg){
  closeLiveSocket();
  DB.auth={token:'',exp:0,uid:''}; persist();
  ME=null; EDIT=null; PLAN=[];
  closeSheet(); closeDoc();
  document.body.classList.remove('authenticated');
  const app=$('#app'), login=$('#login');
  if(app){app.classList.add('hide');app.style.removeProperty('display');app.setAttribute('aria-hidden','true');}
  if(login){login.classList.remove('hide');login.style.removeProperty('display');login.removeAttribute('aria-hidden');}
  $('#lPass').value=''; $('#lPass2').value=''; $('#lPass2').classList.add('hide');
  paintLogin();
  $('#lErr').textContent=msg||'Сессия закончилась — войдите заново';
}
async function doLogout(){
  closeLiveSocket();
  try{ if(DB.auth.token) await api('/logout',{method:'POST'}); }catch(e){}
  DB.auth={token:'',exp:0,uid:''}; persist();
  location.reload();
}

