document.addEventListener('keydown',e=>{
  if($('#login')?.classList.contains('hide')) return;
  if(e.key==='Escape') toggleLoginUserMenu(false);
  if((e.key==='ArrowDown'||e.key==='ArrowUp') && document.activeElement===$('#lUserBtn')){
    e.preventDefault(); const ids=MANAGERS.map(x=>x.id), cur=ids.indexOf($('#lUser').value); const d=e.key==='ArrowDown'?1:-1;
    chooseLoginUser(ids[(cur+d+ids.length)%ids.length]); $('#lUserBtn').focus();
  }
});
