document.addEventListener('click',e=>{
  const pf=e.target.closest('[data-pf]');
  if(pf){ setPFilter(pf.dataset.pf); return; }
  const pw=e.target.closest('[data-power]');
  if(pw){ const x=pw.dataset.power; if(x==='cart')go('cart'); else if(x==='sync')vSync(); else if(x==='attention')vAttention(); return; }
  const qv=e.target.closest('[data-quick-view]'); if(qv){go(qv.dataset.quickView);return;}
  const ch=e.target.closest('[data-cat]');
  if(ch){ setCat(ch.dataset.cat); return; }
  const badd=e.target.closest('[data-badd]');
  if(badd){ const k=badd.dataset.badd;
    setBonus(k,(draft().bonus[k]||0)+1);
    paintBonusList(); paintBonusRows(); return; }
  const bx=e.target.closest('[data-bx]');
  if(bx&&bx.tagName!=='INPUT'){
    const k=bx.closest('.crow').dataset.bk, cur=draft().bonus[k]||0;
    if(bx.dataset.bx==='+') setBonus(k,cur+1);
    if(bx.dataset.bx==='-') setBonus(k,cur-1);
    if(bx.dataset.bx==='del') setBonus(k,0);
    paintBonusList(); paintBonusRows(); return;
  }
  const pk=e.target.closest('[data-park]');
  if(pk){
    const [act,idx]=pk.dataset.park.split(':'), list=DB.parked[ME.id]||[], item=list[+idx];
    if(!item) return;
    if(act==='del'){ if(!confirm('Удалить отложенный заказ «'+(item.name||'')+'»?'))return;
      list.splice(+idx,1); save(); render(); toast('Удалён'); return; }
    if(act==='take'){
      const cur=cartLines().length||bonusLines().length;
      if(cur&&!confirm('Текущий набор будет заменён. Продолжить?')) return;
      DB.drafts[ME.id]={items:Object.assign({},item.items),prices:Object.assign({},item.prices),
        bonus:Object.assign({},item.bonus||{})};
      PLAN=(item.plan||[]).slice();
      list.splice(+idx,1); save(); recalcUsed(); clampDraft(); render();
      const fc=$('#fClient'); if(fc&&item.name&&item.name!=='Без названия') fc.value=item.name;
      toast('Заказ восстановлен');
      return;
    }
  }
  const dayBtn=e.target.closest('[data-day]');
  if(dayBtn){ DDUE=''; OF.preset='date'; OF.date=dayBtn.dataset.day;
    if(dayBtn.dataset.day===today()) OF.preset='today';
    paintOchips(); paintOrders(); return; }
  const cx=e.target.closest('[data-cx]');
  if(cx&&cx.tagName!=='INPUT'&&cx.dataset.cx==='pback'){
    const a=cx.closest('.crow').dataset.ca;
    delete draft().prices[a]; save();
    const row=document.querySelector('.crow[data-ca="'+CSS.escape(a)+'"]');
    if(row&&PROD[a]) row.outerHTML=cartRow(cartLines().find(x=>x.a===a));
    paintCartTotals(); paintFab(); return;
  }
  if(cx&&cx.tagName!=='INPUT'){
    const a=cx.closest('.crow').dataset.ca, cur=draft().items[a]||0;
    if(cx.dataset.cx==='+') setQty(a,cur+1);
    if(cx.dataset.cx==='-') setQty(a,cur-1);
    if(cx.dataset.cx==='del'){
      const back=cur, price=draft().prices[a];
      setQty(a,0);
      toastUndo('Позиция убрана из заказа',()=>{
        setQty(a,back); if(price!=null) draft().prices[a]=price;
        save(); render(); });
    }
    patchCartRow(a); return;
  }
  const fl=e.target.closest('[data-f]');
  if(fl){ const [k,v]=fl.dataset.f.split(':');
    DDUE='';
    if(k==='preset'){ OF.preset=v; if(v!=='date') OF.date=''; }
    else if(k==='month'){ OF.preset=(OF.preset==='month'&&OF.month===v)?'all':'month'; OF.month=v; }
    else if(k==='reset'){ OF={q:OF.q,uid:'',status:'',preset:'all',date:'',month:''}; }
    else OF[k]=(OF[k]===v)?'':v;
    paintOchips(); paintOrders(); return; }
  const st=e.target.closest('[data-x]');
  if(st){ const card=st.closest('.p'); if(!card) return;
    const a=card.dataset.a,d=draft(), before=d.items[a]||0;
    if(st.dataset.x==='+') setQty(a,before+1);
    if(st.dataset.x==='-') setQty(a,before-1);
    if(st.dataset.x!=='set'&&st.dataset.x!=='price'){ patchRow(card,a); if(/^\+\d/.test(st.dataset.x)) card.outerHTML=pRow(PROD[a]); }
    if(st.dataset.x==='+'&&before===0){ setTimeout(()=>{const n=document.querySelector('.p[data-a="'+CSS.escape(a)+'"]');if(n){n.classList.add('just-added');setTimeout(()=>n.classList.remove('just-added'),800)}},0); }
    return; }
  const dc=e.target.closest('[data-dc]');
  if(dc){ DCLIENT=dc.dataset.dc; render(); return; }
  const o=e.target.closest('[data-o]'); if(o){ openOrder(o.dataset.o); return; }
});
document.addEventListener('change',e=>{
  const t=e.target;
  if(t.dataset&&t.dataset.bx==='set'){
    const k=t.closest('.crow').dataset.bk;
    setBonus(k,t.value); paintBonusList(); paintBonusRows(); return;
  }
  if(t.dataset&&t.dataset.cx==='set'){
    const a=t.closest('.crow').dataset.ca;
    setQty(a,parseInt(t.value,10)); patchCartRow(a); return;
  }
  if(t.dataset&&t.dataset.cx==='price'){
    if(!meCfg().freePrice) return;
    const a=t.closest('.crow').dataset.ca;
    const v=Math.max(0,parseInt(String(t.value).replace(/\D/g,''),10)||0);
    const d=draft();
    if(v>0) d.prices[a]=v; else delete d.prices[a];
    save(); patchCartRow(a); return;
  }
  if(t.dataset&&t.dataset.x==='set'){ const c=t.closest('.p'); setQty(c.dataset.a,parseInt(t.value,10)); patchRow(c,c.dataset.a); }
  if(t.dataset&&t.dataset.x==='price'){ const c=t.closest('.p'), a=c.dataset.a;
    const v=Math.max(0,parseInt(String(t.value).replace(/\s/g,''),10)||0);
    draft().prices[a]=v; save(); paintFab(); }
});
document.addEventListener('keydown',e=>{
  const tag=(e.target&&e.target.tagName||'').toLowerCase(), typing=['input','textarea','select'].includes(tag);
  if(e.key==='Escape'){if(document.getElementById('orderActionOverlay')){closeOrderActionSheet();return}closeSheet();closeDoc();return}
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();quickActions();return}
  if(!typing&&e.key==='/'){e.preventDefault();if(VIEW!=='price')go('price');setTimeout(()=>$('#q')?.focus(),60);return}
  if(!typing&&e.altKey&&/^[1-7]$/.test(e.key)){
    const ids=['price','cart','orders','debts','ret','stats','admin']; const x=ids[+e.key-1];
    if(x&&(x!=='admin'||isAdmin())){e.preventDefault();go(x)}
  }
});
window.addEventListener('resize',()=>{paintTop();paintTabs();});


