function ta22ProductCard(p){const st=stockOf(p.a),q=draft().items[p.a]||0,v=viewPrice(p),fav=TA22.fav.has(String(p.a));return `<div class="p${q?' in':''}" data-a="${esc(p.a)}"><button class="ta22-fav${fav?' on':''}" data-fav22="${esc(p.a)}" aria-label="${fav?'Убрать из избранного':'В избранное'}">${fav?'♥':'♡'}</button><div class="in2"><div class="phead"><span class="a">SKU ${esc(p.a)}</span><span class="st${st<=5&&st>0?' low':''}"><i></i>${st>0?st+' в наличии':'нет в наличии'}</span></div><div class="ta22-product-art">${ta22Photo(p)}</div><div class="n" title="${esc(p.n)}">${esc(p.n)}</div><div class="pprice"><span class="pr">${money(v.now)} <em>${CFG.ВАЛЮТА}</em></span>${v.showDisc?`<span class="op">${money(v.base)}</span><span class="tag t-acc">−${Math.round(v.disc*100)}%</span>`:''}</div><div class="stepper">${st<=0&&!q?'<button class="add" disabled>Нет на складе</button>':q?`<button data-x="-" aria-label="Убрать одну">−</button><input data-x="set" inputmode="numeric" value="${q}" aria-label="Количество"><button data-x="+" ${q>=st?'disabled':''} aria-label="Добавить одну">+</button>`:`<button class="add" data-x="+"><span>＋</span> В заказ</button>`}${q&&v.edit?`<input class="px" data-x="price" inputmode="numeric" value="${v.now}" title="Своя цена">`:''}</div></div></div>`}
