function ta22PaintCats(){const box=$('#ta22Cats');if(!box)return;const counts=new Map();CATALOG.prods.forEach(p=>counts.set(p.c,(counts.get(p.c)||0)+(stockOf(p.a)>0?1:0)));const ranked=[...counts].filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);const arr=TA22.catMore?ranked:ranked.slice(0,9);box.innerHTML=`<button class="ta22-cat ${CAT===null?'on':''}" data-cat22="all">Все <b>${ta22StockCounts().avail}</b></button>${arr.map(([c,n])=>`<button class="ta22-cat ${CAT===c?'on':''}" data-cat22="${c}">${esc((CATALOG.cats[c]||'Категория').replace(/\s*[-–—].*$/,'').slice(0,28))}<b>${n}</b></button>`).join('')}${ranked.length>9?`<button class="ta22-cat" data-catmore22>${TA22.catMore?'Свернуть':'Еще'} <b>${Math.max(0,ranked.length-9)}</b></button>`:''}`}
