function ta22ClientStats(){const m=new Map();myOrders().filter(o=>o.status!=='Отменён').forEach(o=>{const k=norm(o.client||'');if(!k)return;let x=m.get(k);if(!x){x={key:k,name:o.client,phone:o.phone||'',orders:0,sales:0,debt:0,last:'',latest:null};m.set(k,x)}x.orders++;x.sales+=MONEY.net(o);x.debt+=MONEY.debt(o);if((o.shipDate||'')>(x.last||'')){x.last=o.shipDate||'';x.latest=o;if(o.phone)x.phone=o.phone}});return [...m.values()].sort((a,b)=>b.sales-a.sales)}
function vClients22(){const arr=ta22ClientStats(),debt=arr.reduce((s,x)=>s+x.debt,0),sales=arr.reduce((s,x)=>s+x.sales,0),active=arr.filter(x=>x.last&&x.last.slice(0,7)===today().slice(0,7)).length;$('#view').innerHTML=`<div class="ta22-pagehead"><div><h2>Клиенты</h2><p>История заказов, оборот и дебиторка в одном месте</p></div><div class="actions"><button id="clientExport22">Excel</button><button class="pri" id="clientNewOrder22">+ Новый заказ</button></div></div><div class="ta22-statrow"><div class="ta22-stat"><u>Клиентов</u><b>${arr.length}</b><i>в истории продаж</i></div><div class="ta22-stat"><u>Активны в месяце</u><b>${active}</b><i>есть отгрузки</i></div><div class="ta22-stat"><u>Оборот</u><b>${money(sales)}</b><i>₸ за всю историю</i></div><div class="ta22-stat"><u>Дебиторка</u><b>${money(debt)}</b><i>₸ к получению</i></div></div><div class="ta22-catalogbar"><div class="ta22-search"><input id="clientQ22" placeholder="Поиск клиента или телефона"><button class="clear" hidden>×</button></div></div><div class="ta22-table"><div class="ta22-tr head"><div>Клиент</div><div>Заказов</div><div>Оборот</div><div>Долг</div><div></div></div><div id="clientRows22"></div></div>`;const paint=()=>{const q=norm($('#clientQ22').value),rows=arr.filter(x=>!q||norm(x.name+' '+x.phone).includes(q));$('#clientRows22').innerHTML=rows.map(x=>`<div class="ta22-tr"><div class="name"><b>${esc(x.name)}</b><span>${esc(x.phone||'нет телефона')} · последняя ${ruDate(x.last)||'—'}</span></div><div class="num">${x.orders}</div><div class="num">${money(x.sales)} ₸</div><div class="num ${x.debt?'debt':''}">${money(x.debt)} ₸</div><div><button data-client22="${esc(x.key)}">Открыть</button></div></div>`).join('')||'<div class="empty">Ничего не найдено</div>'};$('#clientQ22').oninput=paint;paint();$('#clientNewOrder22').onclick=()=>go('price');$('#clientExport22').onclick=async()=>{try{await saveXLSX('Trade Agent Manager — клиенты '+today()+'.xlsx',[{name:'Клиенты',rows:[['Клиент','Телефон','Заказов','Оборот','Долг','Последняя отгрузка'],...arr.map(x=>[x.name,x.phone,x.orders,x.sales,x.debt,ruDate(x.last)])]}]);toast('Excel сохранён')}catch(e){toast('Не удалось выгрузить Excel')}}}
function ta22OpenClient(key){const x=ta22ClientStats().find(v=>v.key===key);if(!x)return;sheet(x.name,`<div class="ta22-statrow"><div class="ta22-stat"><u>Заказов</u><b>${x.orders}</b></div><div class="ta22-stat"><u>Оборот</u><b>${money(x.sales)}</b><i>₸</i></div><div class="ta22-stat"><u>Долг</u><b>${money(x.debt)}</b><i>₸</i></div><div class="ta22-stat"><u>Последняя</u><b style="font-size:14px">${ruDate(x.last)||'—'}</b></div></div><div class="btns"><button class="btn pri" data-cact22="repeat">Повторить последний заказ</button><button class="btn" data-cact22="orders">Все заявки</button><button class="btn" data-cact22="debt">Дебиторка клиента</button></div>`,el=>el.querySelectorAll('[data-cact22]').forEach(b=>b.onclick=()=>{const a=b.dataset.cact22;closeSheet();if(a==='repeat'&&x.latest)return setTimeout(()=>repeatOrderToDraft(x.latest),80);if(a==='orders'){OF={q:x.name,uid:'',status:'',preset:'all',date:'',month:''};return go('orders')}if(a==='debt'){DCLIENT=x.name;return go('debts')}}))}

function ta22Suppliers(){return Array.isArray(DB.settings.suppliers)?DB.settings.suppliers:[]}
function vSuppliers22(){const list=ta22Suppliers();$('#view').innerHTML=`<div class="ta22-pagehead"><div><h2>Поставщики</h2><p>Единый справочник для Manager и будущего Trade Agent Desktop</p></div><div class="actions">${isAdmin()?'<button class="pri" id="supplierAdd22">+ Добавить</button>':''}</div></div><div class="ta22-statrow"><div class="ta22-stat"><u>Поставщиков</u><b>${list.length}</b><i>в общей базе</i></div><div class="ta22-stat"><u>Контактов</u><b>${list.filter(x=>x.phone||x.contact).length}</b><i>заполнено</i></div><div class="ta22-stat"><u>Контур</u><b style="font-size:15px">LIVE</b><i>синхронизация</i></div><div class="ta22-stat"><u>Доступ</u><b style="font-size:15px">${isAdmin()?'EDIT':'READ'}</b><i>${isAdmin()?'можно менять':'только просмотр'}</i></div></div><div class="ta22-supplier-grid">${list.length?list.map(s=>`<div class="ta22-supplier"><div class="logo">${esc(ta22Initials(s.name))}</div><h3>${esc(s.name)}</h3><p>${esc([s.contact,s.phone].filter(Boolean).join(' · ')||'Контакты не указаны')}<br>${esc(s.note||'')}</p>${isAdmin()?`<footer><button data-supedit22="${esc(s.id)}">Изменить</button><button class="dz" data-supdel22="${esc(s.id)}">Удалить</button></footer>`:''}</div>`).join(''):'<div class="empty"><b>Справочник пока пуст</b><span>Администратор может добавить поставщиков. Данные будут синхронизированы через общую базу.</span></div>'}</div>`;$('#supplierAdd22')?.addEventListener('click',()=>ta22SupplierEdit());}
function ta22SupplierEdit(id){const old=ta22Suppliers().find(x=>x.id===id)||{id:'s'+Date.now(),name:'',contact:'',phone:'',note:''};sheet(id?'Поставщик':'Новый поставщик',`<label class="f"><span>Название</span><input class="inp" id="supName22" value="${esc(old.name)}"></label><label class="f"><span>Контакт</span><input class="inp" id="supContact22" value="${esc(old.contact||'')}"></label><label class="f"><span>Телефон</span><input class="inp" id="supPhone22" value="${esc(old.phone||'')}"></label><label class="f"><span>Комментарий</span><textarea class="inp" id="supNote22">${esc(old.note||'')}</textarea></label><button class="btn pri" id="supSave22">Сохранить</button>`,el=>$('#supSave22').onclick=()=>{const name=$('#supName22').value.trim();if(!name){toast('Укажите название');return}const list=ta22Suppliers().slice(),rec={id:old.id,name,contact:$('#supContact22').value.trim(),phone:$('#supPhone22').value.trim(),note:$('#supNote22').value.trim()};const i=list.findIndex(x=>x.id===old.id);if(i>=0)list[i]=rec;else list.unshift(rec);DB.settings.suppliers=list;save();enqueue('settings.set',{settings:DB.settings});closeSheet();go('suppliers');toast('Поставщик сохранён')})}
function ta22SupplierDelete(id){if(!isAdmin())return;const x=ta22Suppliers().find(v=>v.id===id);if(!x||!confirm('Удалить поставщика «'+x.name+'»?'))return;DB.settings.suppliers=ta22Suppliers().filter(v=>v.id!==id);save();enqueue('settings.set',{settings:DB.settings});render();toast('Поставщик удалён')}

function ta22TopProducts(list,n=5){const m=new Map();list.filter(o=>o.status!=='Отменён').forEach(o=>(o.items||[]).filter(i=>!i.bonus).forEach(i=>{let x=m.get(i.a)||{a:i.a,n:i.n,q:0,s:0};x.q+=+i.q||0;x.s+=+i.sum||0;m.set(i.a,x)}));return [...m.values()].sort((a,b)=>b.s-a.s).slice(0,n)}
function vReports22(){vStats();const list=myOrders().filter(o=>o.status!=='Отменён'),clients=ta22ClientStats().slice(0,5),tops=ta22TopProducts(list,5),days=[...Array(14)].map((_,k)=>{const d=addDays(today(),-13+k);return list.filter(o=>o.shipDate===d).reduce((s,o)=>s+MONEY.net(o),0)}),mx=Math.max(1,...days);const wrap=document.createElement('div');wrap.innerHTML=`<div class="ta22-pagehead"><div><h2>Аналитика</h2><p>Продажи, клиенты, товары и контроль дебиторки</p></div><div class="actions"><button id="reportAudit22">Журнал действий</button></div></div><div class="ta22-report-hero"><div class="ta22-report-panel"><h3>Динамика продаж · 14 дней</h3><div class="ta22-bars">${days.map(v=>`<i title="${money(v)} ₸" style="height:${Math.max(4,Math.round(v/mx*100))}%"></i>`).join('')}</div></div><div class="ta22-report-panel"><h3>Топ клиентов</h3>${clients.map((x,i)=>`<div class="ta22-rank"><b>${i+1}. ${esc(x.name)}</b><span>${money(x.sales)} ₸</span></div>`).join('')||'<div class="empty">Нет данных</div>'}</div></div><div class="ta22-report-panel" style="margin-bottom:13px"><h3>Топ товаров по выручке</h3>${tops.map((x,i)=>`<div class="ta22-rank"><b>${i+1}. ${esc(x.n)}</b><span>${x.q} шт · ${money(x.s)} ₸</span></div>`).join('')||'<div class="empty">Нет данных</div>'}</div>`;$('#view').prepend(...wrap.childNodes);$('#reportAudit22').onclick=()=>go('audit')}

function ta22Presence(m){const p=DB.presence[m.id],mins=p?Math.max(0,Math.round((Date.now()+(DB.skew||0)-(p.at||0))/60000)):null;if(mins==null)return{txt:'не подключён',on:false};if(mins<15)return{txt:'сейчас в приложении',on:true};if(mins<60)return{txt:mins+' мин назад',on:false};if(mins<1440)return{txt:Math.round(mins/60)+' ч назад',on:false};return{txt:Math.round(mins/1440)+' дн назад',on:false}}
