function vAuditPage22(){if(!isAdmin()){go('price');return}auditEvent23('открыл журнал','система','','');$('#view').innerHTML=`<div class="ta22-pagehead"><div><h2>Журнал действий</h2><p>Серверный аудит действий пользователей и операций</p></div><div class="actions"><button id="auditReload22">↻ Обновить</button></div></div><div class="ta22-audit-toolbar"><input class="inp" id="auditQ22" placeholder="Поиск по заявке, клиенту, действию…"><select class="inp" id="auditUser22"><option value="">Все пользователи</option></select><select class="inp" id="auditAct22"><option value="">Все действия</option></select><span></span></div><div id="auditState22" class="empty"><b>Загружаю журнал…</b></div>`;const loadAudit=async()=>{try{const r=await api('/audit?limit=200',{timeout:15000}),log=(r.log||[]).slice().sort((a,b)=>(b.at||0)-(a.at||0));TA22.auditCache=log;const users=[...new Set(log.map(x=>x.name).filter(Boolean))].sort(),acts=[...new Set(log.map(x=>x.act).filter(Boolean))].sort();$('#auditUser22').innerHTML='<option value="">Все пользователи</option>'+users.map(x=>`<option>${esc(x)}</option>`).join('');$('#auditAct22').innerHTML='<option value="">Все действия</option>'+acts.map(x=>`<option>${esc(x)}</option>`).join('');const paint=()=>{const q=norm($('#auditQ22').value),u=$('#auditUser22').value,a=$('#auditAct22').value,arr=log.filter(x=>(!u||x.name===u)&&(!a||x.act===a)&&(!q||norm([x.act,x.entity,x.id,x.name,x.info].join(' ')).includes(q)));$('#auditState22').className='ta22-audit-list';$('#auditState22').innerHTML=arr.map(x=>{const bad=/удал|ошиб|неудач|отклонил/i.test(x.act),warn=/оплат|возврат|сброс|код/i.test(x.act);return `<div class="ta22-audit-row ${bad?'bad':warn?'warn':''}"><span class="dot"></span><div><b>${esc(x.act)}</b><span>${esc(x.entity||'')}${x.id?' · '+esc(x.id):''}${x.info?' · '+esc(x.info):''}</span></div><em>${esc(x.name||x.uid||'')}</em><time>${new Date(x.at).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</time></div>`}).join('')||'<div class="empty">Ничего не найдено</div>'};['auditQ22','auditUser22','auditAct22'].forEach(id=>$('#'+id).addEventListener(id==='auditQ22'?'input':'change',paint));paint();if(r.degraded)toast('Журнал открыт в резервном режиме')}catch(e){$('#auditState22').className='empty err';$('#auditState22').innerHTML='<b>Не удалось загрузить журнал</b><span>'+esc(String(e.message||e))+'</span><button class="btn" id="auditRetryStable" style="margin-top:10px">Повторить</button>'}};$('#auditReload22').onclick=loadAudit;loadAudit()}

function ta22MoreCart(){const canPrice=!!meCfg().freePrice;sheet('Еще · Новый заказ',`<div class="ta22-cart-more"><button data-cartmore22="park"><b>Сохранить черновик</b><span>Отложить заказ и вернуться позже</span></button><button data-cartmore22="import"><b>Импорт из Excel</b><span>Артикул + количество</span></button><button data-cartmore22="scan"><b>Сканер штрихкода</b><span>Камера или ручной ввод артикула</span></button>${canPrice?'<button data-cartmore22="discount"><b>Применить скидку</b><span>К текущему заказу</span></button>':''}<button data-cartmore22="bonus"><b>Бонусный товар</b><span>Открыть список бонусов</span></button><button class="danger" data-cartmore22="clear"><b>Очистить заказ</b><span>Удалить позиции из черновика</span></button></div>`)}
function ta22DecorateCart(){const v=$('#view');if(!v)return;/* legacy toolbar intentionally removed: v23 has the single visible order toolbar */const old=v.querySelector(':scope > .btns.two');if(old)old.classList.add('ta22-hidden-actions')}
function ta22ImportOrder(){const inp=document.createElement('input');inp.type='file';inp.accept='.xlsx,.xls,.csv,.txt';inp.onchange=async()=>{const f=inp.files&&inp.files[0];if(!f)return;try{toast('Читаю файл…');let rows;if(/\.csv$|\.txt$/i.test(f.name)){rows=splitRows(await f.text())}else{await loadXLSX();const wb=XLSX.read(await f.arrayBuffer(),{type:'array',codepage:1251});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,raw:false,defval:''})}let hi=-1,ai=0,qi=1;for(let r=0;r<Math.min(20,rows.length);r++){const a=rows[r].map(x=>norm(x));const xa=a.findIndex(x=>/артик|sku|код/.test(x)),xq=a.findIndex(x=>/кол|qty|quantity/.test(x));if(xa>=0&&xq>=0){hi=r;ai=xa;qi=xq;break}}let ok=0,miss=0;for(let r=hi+1;r<rows.length;r++){const art=String(rows[r][ai]||'').trim(),q=Math.max(0,Math.floor(num(rows[r][qi])||0));if(!art||!q)continue;const p=PROD[art];if(!p){miss++;continue}const can=stockOf(art),take=Math.min(can,q);if(take>0){setQty(art,Math.min(can,(draft().items[art]||0)+take));ok++}}save();auditEvent23('импортировал заказ','заказ','черновик',ok+' позиций'+(miss?' · не найдено '+miss:''));closeSheet();render();toast('Импортировано '+ok+' поз.'+(miss?' · не найдено '+miss:''))}catch(e){toast('Ошибка импорта: '+String(e.message||e).slice(0,60))}};inp.click()}
function ta22Scan(){sheet('Сканер товара',`<div class="note">Наведите камеру на штрихкод. Если браузер не поддерживает распознавание, введите артикул вручную.</div><video id="scanVideo22" playsinline style="width:100%;max-height:300px;border-radius:14px;background:#000;margin:9px 0" hidden></video><label class="f"><span>Артикул / код</span><input class="inp" id="scanManual22" inputmode="text" placeholder="Например 84004"></label><button class="btn pri" id="scanFind22">Найти и добавить</button>`);const add=code=>{const p=PROD[String(code).trim()];if(!p){toast('Товар с таким артикулом не найден');return}if(stockOf(p.a)<=0){toast('Товара нет в наличии');return}setQty(p.a,(draft().items[p.a]||0)+1);save();auditEvent23('использовал сканер','товар',p.a,p.n);closeSheet();render();toast('Добавлено: '+p.n)};$('#scanFind22').onclick=()=>add($('#scanManual22').value);if('BarcodeDetector'in window&&navigator.mediaDevices?.getUserMedia){navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}}).then(stream=>{const video=$('#scanVideo22');video.hidden=false;video.srcObject=stream;video.play();const det=new BarcodeDetector({formats:['ean_13','ean_8','code_128','qr_code']});let stop=false;const scan=async()=>{if(!document.body.contains(video)){stream.getTracks().forEach(t=>t.stop());return}try{const r=await det.detect(video);if(r[0]?.rawValue){stream.getTracks().forEach(t=>t.stop());add(r[0].rawValue);return}}catch(_){}setTimeout(scan,350)};scan()}).catch(()=>{})}}
function ta22ApplyDiscount(){const pct=Math.max(0,Math.min(95,Number(prompt('Скидка на текущий заказ, %','10'))||0));if(!pct)return;const d=draft();cartLines().forEach(i=>{const p=PROD[i.a];if(p)d.prices[i.a]=Math.round(viewPriceBase(p)*(1-pct/100))});save();render();toast('Скидка '+pct+'% применена к заказу')}
const _vCart22Legacy=vCart;vCart=function(){_vCart22Legacy();ta22DecorateCart()};

function ensureChrome22(){const who=document.querySelector('#top .who');if(who&&!$('#ta22Bell')){const b=document.createElement('button');b.id='ta22Bell';b.className='ta22-bell';b.setAttribute('aria-label','Центр внимания');b.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg><i></i>';who.insertBefore(b,$('#meBtn'));b.onclick=vAttention}const badge=$('#ta22Bell i');if(badge){const n=attentionData().total;badge.textContent=n>99?'99+':n;badge.hidden=!n}}
paintTop=function(){const titles={price:'Каталог',cart:'Новый заказ',orders:'Заявки',debts:'Долги',ret:'Возвраты',clients:'Клиенты',reports:'Отчеты',stats:'Отчеты',users:'Пользователи',audit:'Журнал действий',admin:'Настройки'};$('#vTitle').textContent=titles[VIEW]||'Trade Agent';const sub=$('#topSub');if(sub){const st=syncState();sub.textContent=(isAdmin()?'ADMIN CONTROL':'FIELD SALES')+' · '+String(st.txt||'').toUpperCase()}$('#sDate').textContent=(DB.stock.date||'нет').replace(/^С\s+/i,'').replace(/\s*по\s+.*$/i,'');$('#sDot').className='dt'+(Date.now()-(DB.stock.at||0)>6048e5?' old':'');$('#meBtn').textContent=ME?(ME.id==='admin'?'АД':ta22Initials(ME.name)):'—';ensureChrome22();paintSync();document.documentElement.style.setProperty('--toph',$('#top').offsetHeight+'px')};
