render=function(){if(!ME)return;if(VIEW==='suppliers')VIEW='price';keepFocus(()=>{paintTop();paintTabs();const map={price:vPrice22,cart:vCart,orders:vOrders,debts:vDebts,ret:vReturns,clients:vClients22,reports:vReports22,stats:vReports22,users:vUsers22,audit:vAuditPage22,admin:vAdmin};(map[VIEW]||vPrice22)();paintFab()})};

vAbout=function(){const st=syncState();sheet('О системе',`<div class="about-hero"><div class="about-logo trade-mark">${TA22MARK}</div><div><span>TRADE AGENT ECOSYSTEM · MANAGER</span><h3>Trade Agent Manager</h3><p>REFERENCE EDITION · v${VERSION}</p></div></div><div class="about-grid"><div><u>Правообладатель</u><b>${esc(APP_OWNER)}</b></div><div><u>Сборка</u><b>${esc(APP_BUILD)}</b></div><div><u>Синхронизация</u><b>${esc(st.txt)}</b></div><div><u>Контур</u><b>Firebase · Firestore LIVE</b></div></div><div class="integration-card"><span>↔</span><div><b>Trade Agent Manager + Trade Agent Desktop</b><i>Единая облачная база Firestore. Менеджерские устройства получают заявки, остатки, пользователей, оплаты, возвраты и фотографии через realtime listeners.</i></div></div><div class="legal-card"><b>© 2026 ${esc(APP_OWNER)}. Все права защищены.</b><p>${esc(APP_FAMILY)} — частный программный продукт. Несанкционированное копирование, распространение, модификация и коммерческое использование без письменного разрешения правообладателя запрещены.</p></div>`)};

