const TA23MARK=TradeAgentBrandMark({small:true});
/* v24.2.8 STABLE FINAL — reference catalog safety helpers */
let TA23_NEW_ONLY=false;
function ta23IsNew(p){
  if(!p) return false;
  const a=String(p.a||'');
  const n=String(p.n||'').toLowerCase();
  const meta=(DB&&DB.productMeta&&DB.productMeta[a])||{};
  return meta.isNew===true || meta.new===true || /(^|\s)(новинка|new)(\s|$)/i.test(n);
}
function ta23StockCounts(){
  const base=ta22StockCounts();
  let newCount=0;
  try{ newCount=CATALOG.prods.reduce((n,p)=>n+(ta23IsNew(p)?1:0),0); }catch(_){ newCount=0; }
  return Object.assign({},base,{newCount});
}
function ta23BrandOf(p){const n=String(p.n||'').toUpperCase();if(/EVO|COLOREVO|REVERSO/.test(n))return 'Selective Professional';if(/ONCARE|DAILY|CURLLOVER|REBUILD|NOYELLOW|SMOOTH|REPAIR|REFILL|SCALP/.test(n))return 'Selective Professional';if(/HEMP/.test(n))return 'Selective Professional';if(/ARTISTIC|PEARL|KERATIN|SHAMPOO|BALSAMO/.test(n))return 'Selective Professional';return 'Professional line'}
function ta23NoPhoto(p){
  const label=esc((p&&p.n)||'Товар');
  return `<div class="ref-no-photo" role="img" aria-label="Нет фотографии: ${label}">
    <svg viewBox="0 0 64 64" aria-hidden="true"><rect x="8" y="13" width="48" height="38" rx="8" fill="none" stroke="currentColor" stroke-width="2"/><path d="M18 42l10-10 7 7 6-6 7 9" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="42" cy="25" r="4" fill="currentColor"/><path d="M17 17l30 30" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>
    <span>Нет фото</span>
  </div>`;
}
function ta23ProductArt(p){const raw=DB&&DB.photos&&(DB.photos[p.a]||DB.photos[String(p.a)]);const src=taPhotoSrc(p.a,raw);if(!src)return ta23NoPhoto(p);return `<img class="ref-real-photo" src="${esc(src)}" alt="${esc(p.n)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="this.parentElement.innerHTML=ta23NoPhoto(PROD[this.closest('.ref-product').dataset.a])">`}
function ta23ProductCard(p){
  const st=stockOf(p.a),q=draft().items[p.a]||0,v=viewPrice(p),fav=TA22.fav.has(String(p.a)),isNew=ta23IsNew(p);
  const step = st<=0&&!q
    ? `<div class="ref-step"><button disabled>−</button><input value="0" disabled><button disabled>+</button></div>`
    : `<div class="ref-step"><button data-x="-" ${!q?'disabled':''}>−</button><input data-x="set" inputmode="numeric" value="${q||1}" aria-label="Количество"><button data-x="+" ${q>=st?'disabled':''}>+</button></div>`;
  return `<article class="p ref-product ref-card-v3${q?' in':''}" data-a="${esc(p.a)}">
    <div class="ref-product-main">
      <div class="ref-art">${ta23ProductArt(p)}</div>
      <div class="ref-content">
        <div class="ref-stockrow"><span class="ref-stock${isNew?' new':''}">${isNew?'Новинка':st>0?'В наличии':'Нет в наличии'}</span>${st>0?`<span class="ref-qty">${st} шт</span>`:''}</div>
        <div class="ref-pname" title="${esc(p.n)}">${esc(p.n)}</div>
        <div class="ref-brand">${esc(ta23BrandOf(p))}</div>
        <div class="ref-sku">SKU ${esc(p.a)}</div>
        <div class="ref-price"><b>${money(v.now)} ₸</b>${v.showDisc?`<s>${money(v.base)} ₸</s><span class="ref-disc">−${Math.round(v.disc*100)}%</span>`:''}</div>
        <div class="ref-buyrow">${step}</div>
      </div>
    </div>
    <aside class="ref-action-rail" aria-label="Действия с товаром">
      <button class="ref-fav${fav?' on':''}" data-fav22="${esc(p.a)}" aria-label="Избранное">${fav?'♥':'♡'}</button>
      ${isAdmin()?`<button class="ref-photo-edit" data-photo-edit="${esc(p.a)}" title="Фото товара" aria-label="Фото товара"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h4l1.5-2h5L16 7h4v12H4z"/><circle cx="12" cy="13" r="3.2"/></svg></button>`:`<span class="ref-action-spacer" aria-hidden="true"></span>`}
      <button class="ref-cartbtn" data-x="+" ${st<=0&&!q?'disabled':''} aria-label="Добавить в заказ">⌑</button>
    </aside>
  </article>`;
}
/* v24.2.8 catalog bridge: reference catalog uses the proven v22 filtering engine.
   The previous build called ta23Products() without defining it, which stopped
   catalog rendering after the toolbar was painted. */
function ta23Products(){ const a=ta22Products(); return TA23_NEW_ONLY?a.filter(ta23IsNew):a; }

function ta23PaintProducts(){const all=ta23Products(),box=$('#refProducts');if(!box)return;const n=Math.min(all.length,TA22.limit),shown=all.slice(0,n);box.className='ref-grid '+(TA22.layout==='list'?'list':'');box.innerHTML=shown.length?shown.map(ta23ProductCard).join(''):'<div class="empty"><b>Ничего не найдено</b><span>Измените поиск или фильтры</span></div>';const more=$('#refLoad');if(more){more.hidden=n>=all.length;more.textContent=`Показать еще · ${all.length-n}`}}
function ta23PaintCats(){const box=$('#refCats');if(!box)return;const counts=new Map();CATALOG.prods.forEach(p=>counts.set(p.c,(counts.get(p.c)||0)+1));const ranked=[...counts].filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);const arr=TA22.catMore?ranked:ranked.slice(0,9);box.innerHTML=`<button class="ref-cat ${CAT===null?'on':''}" data-cat22="all">Все <b>${CATALOG.prods.length}</b></button>${arr.map(([c,n])=>`<button class="ref-cat ${CAT===c?'on':''}" data-cat22="${c}">${esc((CATALOG.cats[c]||'Категория').replace(/\s*[-–—].*$/,'').slice(0,22))} <b>${n}</b></button>`).join('')}${ranked.length>9?`<button class="ref-cat" data-catmore22>${TA22.catMore?'Свернуть':'Еще'} <b>${Math.max(0,ranked.length-9)}</b></button>`:''}`}
function ta23PaintKpis(){const c=ta23StockCounts(),box=$('#refKpis');if(!box)return;box.innerHTML=`<button class="ref-kpi" data-stock22="all"><span class="ki">⌘</span><span><b>${c.total}</b><span>Товаров в каталоге</span></span></button><button class="ref-kpi mint" data-stock22="available"><span class="ki">▣</span><span><b>${c.avail}</b><span>В наличии</span></span></button><button class="ref-kpi warn" data-stock22="low"><span class="ki">△</span><span><b>${c.low}</b><span>Низкий остаток</span></span></button><button class="ref-kpi bad" data-stock22="out"><span class="ki">⌘</span><span><b>${c.out}</b><span>Нет в наличии</span></span></button><button class="ref-kpi mint${TA23_NEW_ONLY?' active':''}" data-new23="1"><span class="ki">✳</span><span><b>${c.newCount}</b><span>Новинки</span></span></button><button class="ref-analytics" id="refAnalytics">Аналитика →</button>`;$('#refAnalytics').onclick=()=>go('reports');box.querySelector('[data-new23]')?.addEventListener('click',()=>{TA23_NEW_ONLY=!TA23_NEW_ONLY;if(TA23_NEW_ONLY){TA22.stock='all';CAT=null}ta23PaintCatalog()})}
function ta23PaintCatalog(){ta23PaintKpis();ta23PaintCats();ta23PaintProducts()}
function vPrice23(){recalcUsed();$('#view').innerHTML=`<section class="ref-catalog"><div class="ref-toolbar"><div class="ref-search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-3-3"/></svg><input id="refQ" placeholder="Поиск по наименованию, бренду, артикулу…" value="${esc(SEARCH)}"><kbd>Ctrl + K</kbd></div><button class="ref-tool filter" id="refFilter"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M4 6h16M7 12h10M10 18h4"/></svg>Фильтры</button>${isAdmin()?`<button class="ref-tool ref-stock-upload" id="refStockUpload" title="Загрузить файл остатков"><span class="ref-stock-upload-ico">↻</span><span>Остатки</span></button>`:''}<div class="ref-layout"><button data-layout22="grid" class="${TA22.layout==='grid'?'on':''}" title="Сетка">▦</button><button data-layout22="list" class="${TA22.layout==='list'?'on':''}" title="Список">☷</button></div><select class="ref-sort" id="refSort"><option value="popular">По популярности</option><option value="stock">По наличию</option><option value="name">По названию</option><option value="price">Цена ↑</option><option value="priceDesc">Цена ↓</option></select></div><div class="ref-kpi-row" id="refKpis"></div><div class="ref-cats" id="refCats"></div><div id="refProducts" class="ref-grid"></div><button id="refLoad" class="ref-load" hidden>Показать еще</button></section>`;const q=$('#refQ');q.oninput=e=>{SEARCH=e.target.value;TA22.limit=90;clearTimeout(vPrice23._t);vPrice23._t=setTimeout(ta23PaintProducts,70)};$('#refFilter').onclick=ta22FilterSheet;$('#refStockUpload')?.addEventListener('click',pickStock);$('#refSort').value=TA22.sort;$('#refSort').onchange=e=>{TA22.sort=e.target.value;localStorage.setItem('ta23.sort',TA22.sort);ta23PaintProducts()};$('#refLoad').onclick=()=>{TA22.limit+=90;ta23PaintProducts()};ta23PaintCatalog()}
function ta23MoreCart(){sheet('Еще',`<div class="action-sheet-grid"><button data-cartmore22="bonus"><span>◆</span><b>Бонусный товар</b><i>Выбрать бесплатную позицию со склада</i></button><button data-cartmore22="scan"><span>▣</span><b>Сканер штрихкода</b><i>Добавить товар камерой</i></button><button data-cartmore22="import"><span>⇩</span><b>Импорт из Excel</b><i>Артикул + количество</i></button><button data-cartmore22="discount"><span>%</span><b>Применить скидку</b><i>На текущий заказ</i></button><button class="danger" data-cartmore22="clear"><span>×</span><b>Очистить заказ</b><i>Удалить все позиции</i></button><button data-cartmore22="park"><span>◷</span><b>Сохранить черновик</b><i>Продолжить позднее</i></button></div>`)}
function ta23OpenBonusPicker(){
  const v=$('#view');
  if(!v) return;
  const bonusSec=[...v.querySelectorAll('.sec')].find(x=>/Бонус к заказу/.test(x.textContent||''));
  if(!bonusSec){ toast('Список бонусных товаров недоступен'); return; }
  const bonusCard=bonusSec.nextElementSibling;
  bonusSec.classList.remove('ref-bonus-block');
  bonusCard?.classList.remove('ref-bonus-block');
  paintBonusList();
  paintBonusRows();
  const list=$('#bList'),open=$('#bOpen');
  if(list&&list.classList.contains('hide')) list.classList.remove('hide');
  if(open){
    open.setAttribute('aria-expanded','true');
    const ico=open.querySelector('i'); if(ico) ico.textContent='▴';
  }
  setTimeout(()=>bonusSec.scrollIntoView({behavior:'smooth',block:'center'}),30);
}

function ta27ClientDirectory(){
  const map=new Map();
  const put=(name,phone,last,source)=>{name=String(name||'').trim(); if(!name)return; const k=norm(name); const cur=map.get(k)||{name,phone:'',last:0,orders:0,source:''};
    if(phone&&!cur.phone)cur.phone=String(phone); cur.last=Math.max(cur.last||0,+last||0); cur.orders+=(source==='order'); if(source)cur.source=source; map.set(k,cur)};
  (DB.clientBook||[]).forEach(x=>put(x.name,x.phone,x.updatedAt||x.at||0,'book'));
  myOrders().forEach(o=>put(o.client,o.phone,o.updatedAt||o.createdAt||0,'order'));
  return [...map.values()].sort((a,b)=>(b.last||0)-(a.last||0)||String(a.name).localeCompare(String(b.name),'ru'));
}
function ta27ApplyClient(x){
  if(!x)return; const fc=$('#fClient'),fp=$('#fPhone'); if(fc)fc.value=x.name||''; if(fp&&x.phone)fp.value=x.phone||'';
  if(!EDIT&&ME){DB.formDrafts[ME.id]=Object.assign({},DB.formDrafts[ME.id]||{},{client:x.name||'',phone:(fp&&fp.value)||x.phone||''});persist()}
  const lab=$('#refClientLabel'); if(lab)lab.textContent=x.name||'Выберите контрагента'; closeSheet();
}
function ta27NewClient(prefill=''){
  sheet('Новый контрагент',`<div class="client-new-form"><label>Название<input class="inp" id="newClientName" value="${esc(prefill)}" placeholder="Название магазина / точки"></label><label>Телефон<input class="inp" id="newClientPhone" type="tel" placeholder="+7"></label><button class="btn pri" id="newClientSave">Сохранить и выбрать</button></div>`,el=>{
    setTimeout(()=>$('#newClientName')?.focus(),120);
    $('#newClientSave')?.addEventListener('click',()=>{const name=($('#newClientName')?.value||'').trim(),phone=($('#newClientPhone')?.value||'').trim(); if(!name){toast('Введите название контрагента');return}
      DB.clientBook=Array.isArray(DB.clientBook)?DB.clientBook:[]; const k=norm(name); const i=DB.clientBook.findIndex(x=>norm(x.name)===k); const rec={name,phone,updatedAt:Date.now()}; if(i>=0)DB.clientBook[i]=Object.assign({},DB.clientBook[i],rec); else DB.clientBook.unshift(rec); save(); enqueue('clientBook.set',{clientBook:DB.clientBook}); ta27ApplyClient(rec); toast('Контрагент выбран')});
  });
}
function ta27PickClient(){
  const data=ta27ClientDirectory();
  sheet('Выбрать контрагента',`<div class="client-picker"><div class="client-search"><input class="inp" id="clientPickQ" placeholder="Поиск по названию или телефону"><button id="clientPickNew">＋ Новый</button></div><div id="clientPickRows"></div></div>`,el=>{
    const paint=()=>{const q=norm($('#clientPickQ')?.value||''); const rows=data.filter(x=>!q||norm((x.name||'')+' '+(x.phone||'')).includes(q)); $('#clientPickRows').innerHTML=rows.length?rows.slice(0,120).map((x,i)=>`<button class="client-pick-row" data-cpick="${i}"><span><b>${esc(x.name)}</b><i>${esc(x.phone||'без телефона')}</i></span><em>${x.orders?x.orders+' заказ.':'выбрать'}</em></button>`).join(''):`<div class="client-pick-empty"><b>Ничего не найдено</b><span>Создайте нового контрагента</span></div>`;
      $('#clientPickRows').querySelectorAll('[data-cpick]').forEach(b=>b.addEventListener('click',()=>ta27ApplyClient(rows[+b.dataset.cpick])));
    };
    $('#clientPickQ')?.addEventListener('input',paint); $('#clientPickNew')?.addEventListener('click',()=>ta27NewClient($('#clientPickQ')?.value||'')); paint(); setTimeout(()=>$('#clientPickQ')?.focus(),120);
  });
}
function ta23DecorateCart(){
  const v=$('#view');if(!v)return;const first=v.querySelector(':scope > .card.pad');const client=$('#fClient')?.value||'Выберите контрагента';
  const bar=document.createElement('div');bar.className='ref-order-bar';
  bar.innerHTML=`<h2>${EDIT?'Редактирование заявки':'Новый заказ'}</h2><button class="ref-order-client" id="refClientFocus"><span>♙</span><strong id="refClientLabel">${esc(client||'Выберите контрагента')}</strong><span>›</span></button><button class="ref-order-btn client-new" id="refNewClient">Новый контрагент</button><button class="ref-order-btn product-add" data-cart23="add">Добавить товар</button><button class="ref-order-btn more" data-cart23="more">Еще⌄</button>`;
  v.prepend(bar);
  if(first){first.style.marginTop='0';first.classList.add('ref-order-details');const helper=document.createElement('div');helper.style.cssText='display:flex;justify-content:flex-end;gap:7px;margin-top:6px';helper.innerHTML='<button class="ref-order-btn" id="refBonusBtn">＋ Бонусный товар</button><button class="ref-order-btn more" id="refCloseDetails">Скрыть условия</button>';first.appendChild(helper);$('#fClient')?.addEventListener('input',()=>{const s=$('#refClientLabel');if(s)s.textContent=$('#fClient').value||'Выберите контрагента'})}
  const itemSec=[...v.querySelectorAll('.sec')].find(x=>/Позиции/.test(x.textContent||''));if(itemSec)itemSec.style.display='none';
  const bonusSec=[...v.querySelectorAll('.sec')].find(x=>/Бонус к заказу/.test(x.textContent||''));if(bonusSec){bonusSec.classList.add('ref-bonus-block');const bcard=bonusSec.nextElementSibling;if(bcard)bcard.classList.add('ref-bonus-block')}
  const cartCard=$('#cartRows')?.closest('.card');if(cartCard)cartCard.classList.add('ref-cart-table');const sum=$('.actbar');if(sum)sum.classList.add('ref-order-act');
  $('#refClientFocus')?.addEventListener('click',ta27PickClient); $('#refNewClient')?.addEventListener('click',()=>ta27NewClient());
  $('#refCloseDetails')?.addEventListener('click',()=>first?.classList.remove('open'));
  $('#refBonusBtn')?.addEventListener('click',ta23OpenBonusPicker)
}

