/* ---------- Фото товара: администратор, по одной позиции ---------- */
function ta24PhotoCompress(file){
  return new Promise((resolve,reject)=>{
    if(!file||!/^image\//i.test(file.type||'')) return reject(new Error('Выберите изображение'));
    if(file.size>12*1024*1024) return reject(new Error('Файл слишком большой'));
    const fr=new FileReader();
    fr.onerror=()=>reject(new Error('Не удалось прочитать файл'));
    fr.onload=()=>{
      const im=new Image();
      im.onerror=()=>reject(new Error('Не удалось открыть изображение'));
      im.onload=()=>{
        try{
          /* Safe product-photo preparation.
             We only trim truly empty/light margins. We DO NOT aggressively detect the object,
             because that can crop a light/yellow/white bottle down to a cap or label. */
          const scanMax=1200;
          const k=Math.min(1,scanMax/Math.max(im.naturalWidth||1,im.naturalHeight||1));
          const sw=Math.max(1,Math.round(im.naturalWidth*k));
          const sh=Math.max(1,Math.round(im.naturalHeight*k));
          const scan=document.createElement('canvas'); scan.width=sw; scan.height=sh;
          const sx=scan.getContext('2d',{willReadFrequently:true});
          sx.fillStyle='#fff'; sx.fillRect(0,0,sw,sh); sx.drawImage(im,0,0,sw,sh);
          const data=sx.getImageData(0,0,sw,sh).data;
          const isBlank=(x,y)=>{
            const i=(y*sw+x)*4, r=data[i], g=data[i+1], b=data[i+2], a=data[i+3];
            return a<10 || (r>246&&g>246&&b>246&&Math.max(r,g,b)-Math.min(r,g,b)<10);
          };
          const rowBlank=(y)=>{let non=0; const step=Math.max(1,Math.floor(sw/350)); for(let x=0;x<sw;x+=step){if(!isBlank(x,y))non++} return non<=1};
          const colBlank=(x)=>{let non=0; const step=Math.max(1,Math.floor(sh/350)); for(let y=0;y<sh;y+=step){if(!isBlank(x,y))non++} return non<=1};
          let minX=0,minY=0,maxX=sw-1,maxY=sh-1;
          while(minY<maxY-8 && rowBlank(minY)) minY++;
          while(maxY>minY+8 && rowBlank(maxY)) maxY--;
          while(minX<maxX-8 && colBlank(minX)) minX++;
          while(maxX>minX+8 && colBlank(maxX)) maxX--;
          /* Never accept an absurd crop: keep the whole image if trimming became suspicious. */
          let cw=maxX-minX+1, ch=maxY-minY+1;
          if(cw<sw*.18 || ch<sh*.18 || cw*ch<sw*sh*.08){minX=0;minY=0;maxX=sw-1;maxY=sh-1;cw=sw;ch=sh}
          const pad=Math.max(8,Math.round(Math.max(cw,ch)*.05));
          minX=Math.max(0,minX-pad); minY=Math.max(0,minY-pad);
          maxX=Math.min(sw-1,maxX+pad); maxY=Math.min(sh-1,maxY+pad);
          cw=maxX-minX+1; ch=maxY-minY+1;

          /* Store a centered square asset. This guarantees predictable rendering in every card. */
          const side=420;
          const c=document.createElement('canvas'); c.width=side; c.height=side;
          const x=c.getContext('2d',{alpha:false});
          x.fillStyle='#fff'; x.fillRect(0,0,side,side);
          const inset=34;
          const scale=Math.min((side-inset*2)/cw,(side-inset*2)/ch);
          const dw=Math.max(1,Math.round(cw*scale)), dh=Math.max(1,Math.round(ch*scale));
          const dx=Math.round((side-dw)/2), dy=Math.round((side-dh)/2);
          x.imageSmoothingEnabled=true; x.imageSmoothingQuality='high';
          x.drawImage(scan,minX,minY,cw,ch,dx,dy,dw,dh);
          let q=.84, out=c.toDataURL('image/jpeg',q);
          while(out.length>65000&&q>.38){q-=.07;out=c.toDataURL('image/jpeg',q)}
          if(out.length>80000) return reject(new Error('Фото не удалось достаточно уменьшить'));
          resolve(out);
        }catch(err){reject(new Error('Не удалось обработать фото'))}
      };
      im.src=fr.result;
    };
    fr.readAsDataURL(file);
  });
}
async function ta24PhotoSaveMap(sku){
  DB.photos=DB.photos||{}; DB.photosAt=Date.now(); save();
  ta23PaintProducts();
  /* Раньше здесь запись (enqueue) не дожидалась подтверждения, а следом сразу
     шёл pull() — полное обновление с сервера. Если запись ещё не успела дойти,
     pull() читал СТАРЫЕ данные и стирал только что загруженное фото прямо
     на этом же устройстве. Теперь ждём реальной записи и не запрашиваем
     принудительное обновление — его подхватит обычный realtime-слушатель. */
  try{
    await enqueue('photo.set',{sku:String(sku),value:DB.photos[String(sku)]||null});
    ta23PaintProducts();
    return true;
  }catch(e){
    toast('Фото не отправлено в общую базу: '+String(e&&e.message||e).slice(0,90));
    return false;
  }
}
