/* =====================================================================
   TRADE AGENT MANAGER 25.1.0 — KV sync + adaptive runtime
   ===================================================================== */
const TA24={version:VERSION,lastForcedPull:0,resizeRAF:0};

/* Reconcile server state periodically even if a revision notification was lost.
   This specifically protects admin-delete -> manager-view convergence. */
async function ta24ForceReconcile(reason){
  if(!ME||!DB.auth.token||!DB.sync.url||SYNCING) return false;
  const now=Date.now();
  if(reason!=='manual' && now-TA24.lastForcedPull<12000) return false;
  TA24.lastForcedPull=now;
  try{
    await pull();
    return true;
  }catch(_){ return false; }
}
function ta24Wake(reason){
  if(!ME) return;
  BACKOFF=0; REV=-1;
  clearTimeout(TA24._wake);
  TA24._wake=setTimeout(()=>{
    tick().catch(()=>{});
    ta24ForceReconcile(reason);
  },80);
}

/* Restore instantly after iOS/Android backgrounding, BFCache and tab focus. */
window.addEventListener('focus',()=>ta24Wake('focus'),{passive:true});
window.addEventListener('pageshow',e=>{ if(e.persisted||document.visibilityState==='visible') ta24Wake('pageshow'); },{passive:true});
document.addEventListener('resume',()=>ta24Wake('resume'),{passive:true});
if(navigator.connection&&navigator.connection.addEventListener){
  navigator.connection.addEventListener('change',()=>ta24Wake('connection'));
}
/* periodic authoritative reconciliation while visible */
/* Firebase realtime: periodic Worker reconciliation removed. */

/* Keep layout aligned with dynamic mobile browser chrome / keyboard. */
function ta24Viewport(){
  cancelAnimationFrame(TA24.resizeRAF);
  TA24.resizeRAF=requestAnimationFrame(()=>{
    const h=(window.visualViewport&&visualViewport.height)||window.innerHeight;
    document.documentElement.style.setProperty('--ta24-vh',Math.round(h)+'px');
    document.documentElement.classList.toggle('ta24-keyboard',window.innerHeight-h>140);
  });
}
window.addEventListener('resize',ta24Viewport,{passive:true});
window.addEventListener('orientationchange',()=>setTimeout(ta24Viewport,120),{passive:true});
if(window.visualViewport){
  visualViewport.addEventListener('resize',ta24Viewport,{passive:true});
  visualViewport.addEventListener('scroll',ta24Viewport,{passive:true});
}
ta24Viewport();

/* Keyboard safety: mobile bottom bars should not cover active fields. */
document.addEventListener('focusin',e=>{
  if(e.target&&/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)){
    document.documentElement.classList.add('ta24-editing');
    setTimeout(()=>{try{e.target.scrollIntoView({block:'center',behavior:'smooth'})}catch(_){}},120);
  }
});
document.addEventListener('focusout',()=>document.documentElement.classList.remove('ta24-editing'));

/* network indicator semantics */
window.addEventListener('online',()=>document.documentElement.classList.remove('ta24-offline'),{passive:true});
window.addEventListener('offline',()=>document.documentElement.classList.add('ta24-offline'),{passive:true});
document.documentElement.classList.toggle('ta24-offline',navigator.onLine===false);


