function fbRestValue(v){
  if(!v||typeof v!=='object')return null;
  if('stringValue' in v)return v.stringValue;
  if('booleanValue' in v)return !!v.booleanValue;
  if('integerValue' in v)return Number(v.integerValue);
  if('doubleValue' in v)return Number(v.doubleValue);
  if('timestampValue' in v)return v.timestampValue;
  if(v.arrayValue)return (v.arrayValue.values||[]).map(fbRestValue);
  if(v.mapValue){
    const out={};
    const f=(v.mapValue&&v.mapValue.fields)||{};
    Object.keys(f).forEach(k=>out[k]=fbRestValue(f[k]));
    return out;
  }
  if('nullValue' in v)return null;
  return null;
}
async function fbLoadLoginDirectory(){
  /* Pre-login directory lookup must never initialize Firestore or block Firebase Auth.
     Read the one public document with a bounded plain HTTP request. If it fails,
     existing local mappings remain usable exactly like v25.0.5. */
  try{
    const url='https://firestore.googleapis.com/v1/projects/'+encodeURIComponent(FIREBASE_CONFIG.projectId)+'/databases/(default)/documents/state/'+encodeURIComponent(FB_LOGIN_DIR_DOC);
    const r=await fbWithTimeout(fetch(url,{cache:'no-store',headers:{'Accept':'application/json'}}),4500,'Каталог входа недоступен');
    if(r&&r.ok){
      const j=await r.json();
      const map=j&&j.fields&&j.fields.map?fbRestValue(j.fields.map):{};
      if(map&&typeof map==='object'){FB_LOGIN_DIR=map;return FB_LOGIN_DIR}
    }
  }catch(_){}
  return FB_LOGIN_DIR||{};
}
function fbAliasEmail(appId){
  const safe=String(appId||'user').toLowerCase().replace(/[^a-z0-9]+/g,'.').replace(/^\.+|\.+$/g,'')||'user';
  const nonce=(Date.now().toString(36)+Math.random().toString(36).slice(2,8)).toLowerCase();
  return `ta.${safe}.${nonce}@tradeagentmanager.app`;
}
async function fbWriteLoginDirectory(appId,email,uid,name){
  if(!isAdmin())throw new Error('Только администратор может менять каталог входа');
  const ref=FBDB.collection('state').doc(FB_LOGIN_DIR_DOC);
  await FBDB.runTransaction(async tx=>{
    const snap=await tx.get(ref),data=snap.exists?(snap.data()||{}):{},map=Object.assign({},data.map||{});
    map[String(appId)]={email:String(email),uid:String(uid||''),name:String(name||''),updatedAt:Date.now()};
    tx.set(ref,{map,updatedAt:Date.now()},{merge:true});
  });
  FB_LOGIN_DIR=Object.assign({},FB_LOGIN_DIR,{[String(appId)]:{email:String(email),uid:String(uid||''),name:String(name||''),updatedAt:Date.now()}});
}
async function fbCreateAliasAccess(appId,password,{role,name,seed}={}){
  if(!isAdmin())throw new Error('Только администратор');
  if(String(password||'').length<6)throw new Error('Код доступа — минимум 6 символов');
  const base=MANAGERS.find(x=>x.id===appId)||{},legacy=Object.assign({},seed||{},(DB.users&&DB.users[appId])||{});
  const alias=fbAliasEmail(appId);
  let app2=firebase.apps.find(a=>a.name==='TradeAgentAliasCreator');
  if(!app2)app2=firebase.initializeApp(FIREBASE_CONFIG,'TradeAgentAliasCreator');
  const auth2=app2.auth();let cred;
  try{cred=await auth2.createUserWithEmailAndPassword(alias,password)}
  finally{try{await auth2.signOut()}catch(_){}}
  const profile=Object.assign(fbProfileFromStatic(appId,cred.user,role||legacy.role||base.role||'manager'),{
    name:name||legacy.name||base.name||appId,
    role:String(role||legacy.role||base.role||'manager').toLowerCase(),
    pay:Array.isArray(legacy.pay)?legacy.pay:(Array.isArray(base.pay)?base.pay:[]),
    freePrice:legacy.freePrice!=null?!!legacy.freePrice:!!base.freePrice,
    seeDisc:legacy.seeDisc!=null?!!legacy.seeDisc:base.seeDisc!==false,
    email:alias,loginAlias:true,createdBy:FBAUTH.currentUser.uid,createdAt:Date.now()
  });
  const oldUid=legacy.firebaseUid&&String(legacy.firebaseUid)!==String(cred.user.uid)?String(legacy.firebaseUid):'';
  const batch=FBDB.batch();
  batch.set(FBDB.collection('users').doc(cred.user.uid),profile);
  if(oldUid)batch.set(FBDB.collection('users').doc(oldUid),{active:false,replacedBy:cred.user.uid,replacedAt:Date.now()},{merge:true});
  await batch.commit();
  await fbWriteLoginDirectory(appId,alias,cred.user.uid,profile.name);
  DB.users=DB.users||{};DB.users[appId]=Object.assign({},base,legacy,profile,{id:appId,firebaseUid:cred.user.uid});
  fbRememberLoginEmail(appId,alias);persist();
  return profile;
}
