function fbUsageMapFor(appId){
  const map={},cut=Number(DB.stock&&DB.stock.at)||0;
  for(const o of (DB.orders||[])){
    if(String(o.uid||'')!==String(appId||'')||o.status==='Отменён')continue;
    if(Number(o.createdAt||0)<=cut)continue;
    const back=MONEY.retQty(o);
    for(const i of (o.items||[])){const q=Math.max(0,Number(i.q||0)-Number(back[i.a]||0));if(q)map[i.a]=(map[i.a]||0)+q}
  }
  return map;
}
