function fbStopListeners(){FB_UNSUB.forEach(f=>{try{f()}catch(_){}});FB_UNSUB=[]}
function fbRenderIfChanged(key,value,apply){const sig=fbSig(value);if(FB_LAST[key]===sig)return;FB_LAST[key]=sig;apply();}
function fbListen(){
  fbStopListeners(); const user=FBAUTH.currentUser;if(!user||!ME)return;
  FB_UNSUB.push(FBDB.collection('users').doc(user.uid).onSnapshot(d=>{
    if(!d.exists||d.data().active===false){doLogout();return}
    const before=ME&&ME.id;fbApplyProfile(d.data(),user);if(before!==ME.id){fbStopListeners();fbPullAll().then(()=>{fbListen();render()}).catch(e=>fbSetStatus(false,e.message))}
  },e=>fbSetStatus(false,e.message)));
  if(isAdmin())FB_UNSUB.push(FBDB.collection('users').onSnapshot(q=>{
    const arr=[];q.forEach(d=>arr.push([d.id,d.data()]));fbRenderIfChanged('users',arr,()=>{arr.forEach(([fid,x])=>{const id=String(x.appId||fid),base=MANAGERS.find(m=>m.id===id)||{};DB.users[id]=Object.assign({},base,x,{id,role:String(x.role||base.role||'manager').toLowerCase(),firebaseUid:fid})});persist();if(VIEW==='users'||VIEW==='admin')render()})
  }));
  FB_UNSUB.push(fbOrdersQuery().onSnapshot(q=>{
    const arr=[],now=Date.now(),tomb=DB.deleted||{};
    q.forEach(d=>{const x=d.data()||{};const t=Number(tomb[x.id]||0);if(t&&now-t<15000)return;arr.push(x)});
    arr.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
    fbRenderIfChanged('orders',arr,()=>{DB.orders=arr;persist();try{recalcUsed();render()}catch(_){}});fbSetStatus(true);
  },e=>fbSetStatus(false,e.message)));
  FB_UNSUB.push(FBDB.collection('state').doc('stock').onSnapshot(d=>{const v=d.exists&&d.data().value;if(v)fbRenderIfChanged('stock',v,()=>{DB.stock=v;persist();recalcUsed();render()})}));
  FB_UNSUB.push(FBDB.collection('state').doc('settings').onSnapshot(d=>{const v=d.exists&&d.data().value;if(v)fbRenderIfChanged('settings',v,()=>{DB.settings=v;persist();render()})}));
  FB_UNSUB.push(FBDB.collection('state').doc('clientBook').onSnapshot(d=>{const v=d.exists&&d.data().value;if(Array.isArray(v))fbRenderIfChanged('clientBook',v,()=>{DB.clientBook=v;persist()})}));
  FB_UNSUB.push(FBDB.collection('usage').onSnapshot(q=>{
    const total={};q.forEach(d=>{const x=d.data()||{},m=x.map||{};for(const a in m)total[a]=(total[a]||0)+Number(m[a]||0)});
    fbRenderIfChanged('usage',total,()=>{DB.usedSrv=total;persist();recalcUsed();if(VIEW==='price')try{ta23PaintCatalog()}catch(_){} });
  },e=>fbSetStatus(false,e.message)));
  FB_UNSUB.push(FBDB.collection('photos').onSnapshot(q=>{
    DB.photos=DB.photos||{};let changed=false;
    q.docChanges().forEach(ch=>{const x=ch.doc.data()||{},sku=String(x.sku||ch.doc.id);if(ch.type==='removed'){if(Object.prototype.hasOwnProperty.call(DB.photos,sku)){delete DB.photos[sku];changed=true}}else if(x.value&&DB.photos[sku]!==x.value){DB.photos[sku]=x.value;changed=true}});
    if(changed){DB.photosAt=Date.now();persist();try{ta23PaintProducts()}catch(_){}}
  },e=>fbSetStatus(false,e.message)));
  LIVE_PUSH=true;fbSetStatus(true);
}
async function fbPullAll(){
  const oq=fbOrdersQuery();
  const jobs=[oq.get(),FBDB.collection('state').doc('stock').get(),FBDB.collection('state').doc('settings').get(),FBDB.collection('state').doc('clientBook').get(),FBDB.collection('photos').get(),FBDB.collection('usage').get()];
  const [orders,stock,settings,clientBook,photos,usage]=await Promise.all(jobs);
  DB.orders=orders.docs.map(d=>d.data()).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
  if(stock.exists&&stock.data().value)DB.stock=stock.data().value;if(settings.exists&&settings.data().value)DB.settings=settings.data().value;
  if(clientBook.exists&&Array.isArray(clientBook.data().value))DB.clientBook=clientBook.data().value;
  const p={};photos.forEach(d=>{const x=d.data()||{};if(x.value)p[String(x.sku||d.id)]=x.value});DB.photos=p;
  const used={};usage.forEach(d=>{const m=(d.data()||{}).map||{};for(const a in m)used[a]=(used[a]||0)+Number(m[a]||0)});DB.usedSrv=used;
  if(isAdmin())await fbPullUsersForAdmin(); persist();recalcUsed();fbSetStatus(true);return true;
}
/* Firestore writes. Draft/local UI saves do NOT rewrite stock/settings anymore. */
enqueue=function(type,payload){
  if(!FB_READY||!FBAUTH||!FBAUTH.currentUser)return Promise.resolve(false);
  return Promise.resolve().then(async()=>{
    if(type==='order.save'||type.startsWith('payment.')||type.startsWith('return.'))await fbPushOrder(payload.id||(payload.order&&payload.order.id));
    else if(type==='order.delete'){if(!isAdmin())throw new Error('Удалять заявки может только администратор');await FBDB.collection('orders').doc(fbSafeId(payload.id)).delete();if(payload.uid)await fbPushUsage(payload.uid);else await fbPushAllUsage()}
    else if(type==='stock.set'){if(!isAdmin())throw new Error('Остатки меняет администратор');await FBDB.collection('state').doc('stock').set({value:fbClean(DB.stock),updatedAt:Date.now()});await fbPushAllUsage()}
    else if(type==='settings.set'){if(!isAdmin())throw new Error('Настройки меняет администратор');await FBDB.collection('state').doc('settings').set({value:fbClean(DB.settings),updatedAt:Date.now()})}
    else if(type==='clientBook.set')await FBDB.collection('state').doc('clientBook').set({value:fbClean(DB.clientBook),updatedAt:Date.now()})
    else if(type==='photo.set'){if(!isAdmin())throw new Error('Фото меняет администратор');await fbPushPhoto(payload.sku)}
    else if(type==='photos.set'){if(!isAdmin())throw new Error('Фото меняет администратор');await fbPushAllPhotos()}
    else if(type==='audit.event')await FBDB.collection('audit').add(Object.assign(fbClean(payload),{at:Date.now(),uid:FBAUTH.currentUser.uid,appId:ME&&ME.id||'',name:ME&&ME.name||''}));
    fbSetStatus(true);
  }).catch(e=>{fbSetStatus(false,e.message);try{toast('Firebase: '+String(e.message||e).slice(0,90))}catch(_){}})
};
/* Critical anti-flicker rule: legacy save() calls flush(); on Firebase it must be a no-op. */
flush=async function(){
  if(!FB_READY||!FBAUTH||!FBAUTH.currentUser)return false;
  const q=Array.isArray(DB.queue)?DB.queue.splice(0):[];
  try{
    for(const op of q){
      if(!op)continue;
      if(op.type==='order.save'&&op.order)await FBDB.collection('orders').doc(fbSafeId(op.order.id)).set(fbClean(op.order));
      else if(op.type==='order.delete'&&isAdmin())await FBDB.collection('orders').doc(fbSafeId(op.id)).delete().catch(()=>{});
    }
    if(q.some(op=>op&&['order.save','order.delete'].includes(op.type))&&isAdmin())await fbPushAllUsage();
    persist();return true;
  }catch(e){DB.queue=q.concat(DB.queue||[]);persist();throw e}
};
