/* v25.2.0 — explicit user + code login. No auth-state handoff is required to enter. */
let FB_LOGIN_ATTEMPTING=false;
async function fbFinishExplicitLogin(user,id,pass,email,bootstrap){
  const profile=await fbWithTimeout(fbEnsureProfile(user),10000,'Не удалось загрузить профиль');
  fbApplyProfile(profile,user);
  fbRememberLoginEmail(id,email||user.email||'');
  FB_LOGIN_ATTEMPTING=false;

  document.body.classList.add('authenticated');
  const login=document.getElementById('login'),app=document.getElementById('app');
  if(login){login.classList.add('hide');login.style.setProperty('display','none','important');login.setAttribute('aria-hidden','true')}
  if(app){app.classList.remove('hide');app.style.removeProperty('display');app.removeAttribute('aria-hidden')}
  const lp=document.getElementById('lPass');if(lp)lp.value='';
  const btn=document.getElementById('lGo');if(btn){btn.disabled=false;btn.classList.remove('login-busy');btn.style.pointerEvents='auto';btn.innerHTML='Войти <span>→</span>'}
  recalcUsed();go('price');

  /* Everything after the successful password check is background work.
     Most importantly, publish the selected-user -> hidden Firebase-email map
     so Safari and an iPhone Home Screen web app do not depend on shared localStorage. */
  Promise.resolve().then(async()=>{
    try{
      if(id==='admin'&&user.email){
        try{await fbWriteLoginDirectory('admin',user.email,user.uid,profile.name||'Администратор')}catch(_){}
      }
      if(bootstrap){
        try{await fbEnsureAdminAlias(pass)}catch(_){}
        finally{FB_PENDING_BIND=null}
      }
      let migrated=false;
      try{migrated=await fbMigrateLocalIfCloudEmpty()}catch(_){}
      if(!migrated){try{await fbPullAll()}catch(_){} }
      try{fbListen()}catch(_){}
      fbSetStatus(true);
      if(isAdmin())setTimeout(()=>fbMigrateLegacyPhotos().catch(()=>{}),1800);
      if(isAdmin())setTimeout(async()=>{try{const m=await FBDB.collection('state').doc('meta').get(),x=m.exists?m.data()||{}:{};if(!x.legacyMigrated&&(DB.orders||[]).length===0)toast('Старая история еще не перенесена · Админка → Восстановить старую базу')}catch(_){}},2200);
    }catch(syncErr){fbSetStatus(false,syncErr&&syncErr.message)}
  });
}

doLogin=async function(){
  if(FB_LOGIN_ATTEMPTING)return;
  const id=(document.getElementById('lUser')?.value||'admin').trim();
  const pass=(document.getElementById('lPass')?.value||'').trim();
  const btn=document.getElementById('lGo');
  const er=document.getElementById('lErr');
  const err=m=>{FB_LOGIN_ATTEMPTING=false;FB_PENDING_BIND=null;if(er)er.textContent=m;if(btn){btn.disabled=false;btn.classList.remove('login-busy');btn.style.pointerEvents='auto';btn.innerHTML='Войти <span>→</span>'}};
  if(!pass)return err('Введите код доступа');
  if(pass.length<6)return err('Код доступа — минимум 6 символов');

  FB_LOGIN_ATTEMPTING=true;
  if(btn){btn.disabled=true;btn.classList.add('login-busy');btn.textContent='Вхожу…'}
  if(er)er.textContent='';

  try{
    /* PWA and Safari do NOT share localStorage on iPhone. Resolve the hidden
       Firebase email from the shared loginDirectory before falling back to a
       one-time admin email prompt. */
    let email=fbLoginEmailFor(id);
    if(!email){
      await fbLoadLoginDirectory();
      email=fbLoginEmailFor(id);
    }
    let bootstrap=false;
    if(!email&&id==='admin'){
      FB_LOGIN_ATTEMPTING=false;
      email=await fbOneTimeAdminEmail();
      if(!email)return err('Для первого входа в ярлыке один раз нужен служебный email администратора.');
      FB_LOGIN_ATTEMPTING=true;bootstrap=true;
      if(btn){btn.disabled=true;btn.classList.add('login-busy');btn.textContent='Вхожу…'}
    }
    if(!email)return err('Для этого пользователя доступ еще не создан. Администратор должен открыть «Пользователи» и нажать «Создать доступ».');

    await fbInit();
    FB_PENDING_BIND=bootstrap?{appId:'admin',password:pass,email}:null;
    const cred=await fbWithTimeout(FBAUTH.signInWithEmailAndPassword(email,pass),15000,'Сервер входа не ответил');
    const user=cred&&cred.user;
    if(!user)throw new Error('Firebase не вернул пользователя');
    await fbFinishExplicitLogin(user,id,pass,email,bootstrap);
  }catch(e){
    const code=e&&e.code;
    err((code&&['auth/invalid-credential','auth/wrong-password','auth/user-not-found'].includes(code))?'Неверный код доступа':String(e&&e.message||e).replace(/^Firebase:\s*/,'').slice(0,140));
  }
};

