async function legacyRequest(path,{method='GET',body,token,timeout=20000}={}){
  const c=new AbortController(),timer=setTimeout(()=>c.abort(),timeout),headers={'Content-Type':'application/json'};
  if(token)headers.Authorization='Bearer '+token;
  try{
    const r=await fetch(LEGACY_API.replace(/\/+$/,'')+path,{method,headers,body:body?JSON.stringify(body):undefined,cache:'no-store',signal:c.signal});
    const j=await r.json().catch(()=>null);
    if(!j)throw new Error('Старый сервер ответил не по формату');
    if(!r.ok)throw Object.assign(new Error(j.error||('HTTP '+r.status)),{code:j.code||'HTTP',status:r.status});
    return j;
  }catch(e){if(e&&e.name==='AbortError')throw new Error('Старый сервер не ответил вовремя');throw e}
  finally{clearTimeout(timer)}
}
async function legacyReadSnapshot(adminCode){
  const login=await legacyRequest('/login',{method:'POST',body:{login:'admin',pass:String(adminCode||''),dev:'Firebase migration '+VERSION},timeout:12000});
  if(!login||!login.token)throw new Error('Старый сервер не выдал сессию');
  const pull=await legacyRequest('/pull?since=0',{token:login.token,timeout:45000});
  if(!pull||!Array.isArray(pull.orders))throw new Error('Старый сервер не вернул заявки');
  let audit={ok:false,log:[],warning:''};
  try{audit=await legacyRequest('/audit?limit=500',{token:login.token,timeout:30000})}catch(e){audit={ok:false,log:[],warning:String(e.message||e)}}
  return {login,pull,audit,readAt:Date.now()};
}
function legacyClientBook(orders){
  const by={};
  (orders||[]).forEach(o=>{const name=String(o.client||'').trim();if(!name)return;const k=norm(name);const at=Number(o.updatedAt||o.createdAt)||0,prev=by[k];if(!prev||at>prev.updatedAt)by[k]={name,phone:String(o.phone||'').trim(),updatedAt:at}});
  return Object.values(by).sort((a,b)=>a.name.localeCompare(b.name,'ru'));
}
async function fbWriteBatches(writes,chunk=300){
  for(let i=0;i<writes.length;i+=chunk){const b=FBDB.batch();for(const w of writes.slice(i,i+chunk))w(b);await b.commit()}
}
async function fbImportLegacySnapshot(pack){
  if(!isAdmin()||!FBAUTH.currentUser)throw new Error('Миграция доступна только администратору');
  const rm=pack&&pack.pull||{}, now=Date.now(), currentUid=FBAUTH.currentUser.uid, currentApp=ME.id;
  const oldOrders=Array.isArray(rm.orders)?rm.orders:[], oldUsers=Array.isArray(rm.users)?rm.users:[];
  const currentQ=await FBDB.collection('orders').get(), currentBy={};currentQ.forEach(d=>{const x=d.data()||{};currentBy[String(x.id||d.id)]=x});
  let importedOrders=0,keptNewer=0;
  const orderWrites=[];
  for(const o of oldOrders){if(!o||!o.id)continue;const cur=currentBy[String(o.id)];if(cur&&Number(cur.updatedAt||0)>Number(o.updatedAt||0)){keptNewer++;continue}orderWrites.push(b=>b.set(FBDB.collection('orders').doc(fbSafeId(o.id)),fbClean(o),{merge:false}));importedOrders++}
  await fbWriteBatches(orderWrites);

  const legacyUsers={};
  for(const u of oldUsers){if(!u||!u.id)continue;const base=MANAGERS.find(m=>m.id===u.id)||{};legacyUsers[u.id]=Object.assign({},base,u,{id:u.id,role:String(u.role||base.role||'manager').toLowerCase()});delete legacyUsers[u.id].pass}
  const usersQ=await FBDB.collection('users').get();
  const userWrites=[];
  usersQ.forEach(d=>{const cur=d.data()||{},id=String(cur.appId||cur.id||'');const old=legacyUsers[id];if(!old)return;const patch={name:old.name||cur.name,role:old.role||cur.role,pay:Array.isArray(old.pay)?old.pay:cur.pay,freePrice:old.freePrice!=null?!!old.freePrice:!!cur.freePrice,seeDisc:old.seeDisc!=null?!!old.seeDisc:cur.seeDisc!==false,legacyRestoredAt:now};userWrites.push(b=>b.set(d.ref,patch,{merge:true}))});
  if(userWrites.length)await fbWriteBatches(userWrites);

  const stateBatch=FBDB.batch();
  if(rm.stock)stateBatch.set(FBDB.collection('state').doc('stock'),{value:fbClean(rm.stock),updatedAt:now,source:'legacy-cloudflare'},{merge:false});
  if(rm.settings)stateBatch.set(FBDB.collection('state').doc('settings'),{value:fbClean(rm.settings),updatedAt:now,source:'legacy-cloudflare'},{merge:false});
  stateBatch.set(FBDB.collection('state').doc('legacyUsers'),{value:fbClean(legacyUsers),updatedAt:now},{merge:false});
  stateBatch.set(FBDB.collection('state').doc('legacyMeta'),{seq:fbClean(rm.seq||{}),deleted:fbClean(rm.deleted||{}),presence:fbClean(rm.presence||{}),serverTime:Number(rm.serverTime)||0,rev:rm.rev||'',updatedAt:now},{merge:false});
  const restoredClientBook=Array.isArray(rm.clientBook)&&rm.clientBook.length?rm.clientBook:legacyClientBook(oldOrders);
  stateBatch.set(FBDB.collection('state').doc('clientBook'),{value:fbClean(restoredClientBook),updatedAt:now,source:Array.isArray(rm.clientBook)&&rm.clientBook.length?'legacy-backup':'derived-from-legacy-orders'},{merge:true});
  stateBatch.set(FBDB.collection('state').doc('meta'),{legacyMigrated:true,legacyMigratedAt:now,legacyOrderCount:oldOrders.length,legacyUserCount:oldUsers.length,source:'cloudflare-v24',schemaVersion:DB.schemaVersion||0,updatedAt:now},{merge:true});
  await stateBatch.commit();

  const seqWrites=[];
  for(const [key,n0] of Object.entries(rm.seq||{})){const n=Number(n0)||0,parts=String(key).split('_'),appId=parts.slice(1).join('_')||'';seqWrites.push(async()=>{const ref=FBDB.collection('sequences').doc(fbSafeId(key));await FBDB.runTransaction(async tx=>{const s=await tx.get(ref),cur=s.exists?Number((s.data()||{}).n||0):0;if(n>cur)tx.set(ref,{key,appId,n,date:parts[0]||'',updatedAt:now,source:'legacy-cloudflare'},{merge:true})})})}
  for(const job of seqWrites)await job();

  const photoMap=(rm.photos&&rm.photos.map&&typeof rm.photos.map==='object')?rm.photos.map:{};
  const photoWrites=[];for(const [sku,value] of Object.entries(photoMap)){if(!value)continue;photoWrites.push(b=>b.set(FBDB.collection('photos').doc(fbSafeId(sku)),{sku:String(sku),value:String(value),updatedAt:now,source:'legacy-cloudflare'},{merge:false}))}
  if(photoWrites.length)await fbWriteBatches(photoWrites,40);

  const auditLog=Array.isArray(pack.audit&&pack.audit.log)?pack.audit.log:[];
  const existingLegacyAudit=new Set();
  try{const aq=await FBDB.collection('audit').where('source','==','legacy-cloudflare').get();aq.forEach(d=>existingLegacyAudit.add(d.id))}catch(_){}
  const auditWrites=[];
  auditLog.forEach((r,i)=>{if(!r)return;const originalUid=String(r.uid||''),docId='legacy_'+fbSafeId(String(r.key||((r.at||0)+'_'+i)));if(existingLegacyAudit.has(docId))return;const rec=Object.assign({},fbClean(r),{uid:currentUid,appId:currentApp,originalUid,originalRole:r.role||'',source:'legacy-cloudflare',migratedAt:now});auditWrites.push(b=>b.set(FBDB.collection('audit').doc(docId),rec,{merge:false}))});
  if(auditWrites.length)await fbWriteBatches(auditWrites);

  DB.orders=oldOrders.slice();DB.stock=rm.stock||DB.stock;DB.settings=Object.assign({},DB.settings||{},rm.settings||{});DB.seq=Object.assign({},rm.seq||{},DB.seq||{});DB.deleted=Object.assign({},rm.deleted||{},DB.deleted||{});DB.presence=Object.assign({},rm.presence||{},DB.presence||{});DB.photos=Object.assign({},photoMap);fbMergeLegacyUsers(legacyUsers);persist();
  await fbPushAllUsage(); await fbPullAll(); fbListen();
  let photoResult={ok:0,fail:0};try{photoResult=await fbMigrateLegacyPhotos()}catch(_){}
  await FBDB.collection('audit').add({at:Date.now(),uid:currentUid,appId:currentApp,name:ME.name||'Администратор',act:'завершил миграцию',entity:'система',id:'Cloudflare → Firebase',info:`заявок ${importedOrders}; пользователей ${oldUsers.length}; журнал ${auditLog.length}; фото ${Object.keys(photoMap).length}`}).catch(()=>{});
  return {orders:importedOrders,keptNewer,users:oldUsers.length,audit:auditLog.length,photos:Object.keys(photoMap).length,photoOk:photoResult.ok||0,photoFail:photoResult.fail||0,auditWarning:(pack.audit&&pack.audit.warning)||''};
}
async function fbLegacyMigrationWizard(box){
  if(!isAdmin())return;
  const inp=document.createElement('input');inp.type='file';
  inp.onchange=async()=>{
    const f=inp.files&&inp.files[0];if(!f)return;
    try{
      if(box)box.textContent='Читаю файл переноса…';
      let pack=JSON.parse(await f.text());
      /* v25.2.0: на iPhone можно восстановиться прямо из штатной резервной копии v24
         (agentcrm-backup-*.json), без локального HTML-моста и Mac. */
      if(pack&&Array.isArray(pack.orders)&&pack.users&&pack.format!=='tradeagent-legacy-migration/1'){
        const oldUsers=Array.isArray(pack.users)?pack.users:Object.entries(pack.users||{}).map(([id,u])=>Object.assign({id},u||{}));
        const oldPhotos=(pack.photos&&pack.photos.map&&typeof pack.photos.map==='object')?pack.photos.map:(pack.photos&&typeof pack.photos==='object'?pack.photos:{});
        pack={
          format:'tradeagent-legacy-migration/1',
          exportedAt:Date.now(),
          source:'agentcrm-backup-v24',
          pull:{
            orders:pack.orders||[], users:oldUsers, stock:pack.stock||null, settings:pack.settings||{},
            photos:{map:oldPhotos}, seq:pack.seq||{}, deleted:pack.deleted||{}, presence:pack.presence||{},
            clientBook:Array.isArray(pack.clientBook)?pack.clientBook:[], serverTime:Number(pack.sync&&pack.sync.at)||0, rev:''
          },
          audit:{ok:false,log:[],warning:'Импорт из резервной копии v24: серверный журнал действий не входил в этот файл.'}
        };
      }
      if(!pack||pack.format!=='tradeagent-legacy-migration/1'||!pack.pull||!Array.isArray(pack.pull.orders))throw new Error('Это не файл миграции TradeAgent');
      const rm=pack.pull,ac=Array.isArray(pack.audit&&pack.audit.log)?pack.audit.log.length:0,pc=rm.photos&&rm.photos.map?Object.keys(rm.photos.map).length:0;
      const ok=confirm(`Файл старой базы прочитан.\n\nЗаявок: ${rm.orders.length}\nПользователей: ${(rm.users||[]).length}\nФото: ${pc}\nСобытий журнала: ${ac}\n\nПеренести в Firebase? Старая база НЕ удаляется.`);
      if(!ok){if(box)box.textContent='Миграция отменена — ничего не изменено.';return}
      if(box)box.textContent='Переношу данные в Firebase. Не закрывайте страницу…';
      const r=await fbImportLegacySnapshot(pack);
      if(box)box.textContent=`Готово. Заявок: ${r.orders}${r.keptNewer?' · сохранено более новых Firebase: '+r.keptNewer:''} · пользователей: ${r.users} · журнал: ${r.audit} · фото: ${r.photos}${r.photoFail?' (не удалось скачать '+r.photoFail+')':''}.`+(r.auditWarning?' Журнал старого сервера: '+r.auditWarning:'');
      toast('Старая база восстановлена в Firebase');render();
    }catch(e){const msg=String(e&&e.message||e||'ошибка').slice(0,220);if(box)box.textContent='Не удалось восстановить: '+msg;toast('Миграция: '+msg.slice(0,100))}
  };
  inp.click();
}

/* Add optional state to regular Firebase reads/listeners. These reads are isolated:
   if the new rules have not been published yet, the rest of the application still opens. */
const fbPullAllBase=fbPullAll;
fbPullAll=async function(){
  await fbPullAllBase();
  const [lu,lm,sq,pr]=await Promise.all([
    fbOptionalGet(FBDB.collection('state').doc('legacyUsers')),
    fbOptionalGet(FBDB.collection('state').doc('legacyMeta')),
    fbOptionalGet(fbSequencesQuery()),
    fbOptionalGet(FBDB.collection('presence'))
  ]);
  if(lu&&lu.exists)fbMergeLegacyUsers((lu.data()||{}).value||{});
  if(lm&&lm.exists)fbApplyLegacyMeta(lm.data()||{});
  if(sq&&sq.forEach)sq.forEach(d=>{const x=d.data()||{};if(x.key)DB.seq[x.key]=Math.max(Number(DB.seq[x.key]||0),Number(x.n||0))});
  if(pr&&pr.forEach){pr.forEach(d=>{const x=d.data()||{};if(x.appId)DB.presence[x.appId]=x})}
  persist();return true;
};
const fbListenBase=fbListen;
fbListen=function(){
  fbListenBase();fbStartPresence();
  try{FB_UNSUB.push(FBDB.collection('state').doc('legacyUsers').onSnapshot(d=>{if(d.exists){fbMergeLegacyUsers((d.data()||{}).value||{});persist();if(VIEW==='users'||VIEW==='admin')render()}}))}catch(_){}
  try{FB_UNSUB.push(fbSequencesQuery().onSnapshot(q=>{q.forEach(d=>{const x=d.data()||{};if(x.key)DB.seq[x.key]=Math.max(Number(DB.seq[x.key]||0),Number(x.n||0))});persist()}))}catch(_){}
  try{FB_UNSUB.push(FBDB.collection('presence').onSnapshot(q=>{DB.presence=DB.presence||{};q.forEach(d=>{const x=d.data()||{};if(x.appId)DB.presence[x.appId]=x});persist();if(VIEW==='users')render()}))}catch(_){}
};
