/* =====================================================================
   v25.2.0 — EXPLICIT LOGIN GATE
   - Never auto-enter from a restored Firebase session.
   - Do NOT sign out or wait for restored auth during startup.
   - The already-bound original login button stays untouched.
   - doLogin() verifies the code and opens the app directly.
   ===================================================================== */
function fbResetLoginUi(){
  try{
    document.body.classList.remove('authenticated');
    const login=document.getElementById('login'),app=document.getElementById('app');
    if(login){login.classList.remove('hide');login.style.removeProperty('display');login.removeAttribute('aria-hidden')}
    if(app){app.classList.add('hide');app.style.removeProperty('display')}
    const b=document.getElementById('lGo');
    if(b){b.disabled=false;b.removeAttribute('disabled');b.classList.remove('login-busy');b.style.pointerEvents='auto';b.innerHTML='Войти <span>→</span>'}
  }catch(_){}
}

fbResetLoginUi();
FB_LOGIN_ATTEMPTING=false;FB_PENDING_BIND=null;
/* Shared directory lookup is best-effort and never blocks the button. */
fbLoadLoginDirectory().catch(()=>{});
/* Firebase initialization is also background-only. The user can tap immediately;
   doLogin() awaits the same promise path itself if initialization is still running. */
fbInit().then(()=>{
  FBAUTH.onAuthStateChanged(user=>{
    /* A restored session never unlocks the workspace. It is deliberately ignored.
       Loss of an accepted session while already inside returns to login. */
    if(!user&&document.body.classList.contains('authenticated')){
      try{relogin('Сессия закончилась — войдите заново')}catch(_){location.reload()}
      return;
    }
    if(!document.body.classList.contains('authenticated')&&!FB_LOGIN_ATTEMPTING){
      const b=document.getElementById('lGo');
      if(b){b.disabled=false;b.removeAttribute('disabled');b.classList.remove('login-busy');b.style.pointerEvents='auto';b.innerHTML='Войти <span>→</span>'}
    }
  });
}).catch(e=>{
  fbSetStatus(false,e.message);
  const er=document.getElementById('lErr');if(er)er.textContent='Firebase не запустился: '+String(e.message||e).slice(0,90);
});

/* No service worker update loop; no version polling; no Worker polling. */
